  "Sostenibilidad, presión ambiental y criterios ESG que pesan en la decisión de compra.": "Sustainability, environmental pressure and ESG criteria that weigh on the buying decision.",
  "Leyes, cumplimiento, contratos, protección de datos y requisitos que abren o frenan la venta.": "Laws, compliance, contracts, data protection and requirements that open or block the sale.",
