  "Amenaza de sustitutos": "Threat of substitutes",
  "Otras formas de resolver el mismo problema que compiten contigo sin ser \"lo mismo\" (in-house, otra categoría).": "Other ways to solve the same problem that compete with you without being \"the same thing\" (in-house, another category).",
  "Poder de negociación de clientes": "Bargaining power of buyers",
  "Cuánta presión pueden meter tus compradores: opciones que tienen, sensibilidad a precio, costo de cambiarte.": "How much pressure your buyers can apply: the options they have, price sensitivity, switching cost.",
  "Poder de negociación de proveedores": "Bargaining power of suppliers",
  "Cuánto dependes de terceros (tecnología, datos, partners) y cuánto eso presiona tus márgenes o tu velocidad.": "How much you depend on third parties (technology, data, partners) and how much that squeezes your margins or your speed.",
  "Lo que haces bien y te da ventaja: tu producto, tu equipo, tu marca, tus casos de éxito.": "What you do well and gives you an edge: your product, your team, your brand, your case studies.",
  "Ej. Time-to-value de 30 días Equipo con experiencia en el sector Casos de éxito comprobados": "E.g., 30-day time to value Team with industry experience Proven case studies",
  "Factores del mercado a tu favor que puedes aprovechar: tendencias, huecos, cambios de demanda.": "Market factors in your favor that you can take advantage of: trends, gaps, shifts in demand.",
  "Ej. Nuevo segmento sin competencia fuerte Regulación que obliga a digitalizar Demanda creciente en LATAM": "E.g., New segment without strong competition Regulation that forces digitalization Growing demand in LATAM",
  "Debilidades": "Weaknesses",
