  "Completar ahora": "Complete now",
  "Tu análisis de mercado está listo. Revísalo y confírmalo en el Intelligence Hub: el Radar crea un detector por cada señal de compra que confirmes.": "Your market analysis is ready. Review and confirm it in the Intelligence Hub: Radar creates a detector for each buying signal you confirm.",
  "Estamos preparando tu análisis de mercado en el Intelligence Hub. Cuando esté listo, revísalo y confírmalo: el Radar diseña su plan sobre él.": "We're preparing your market analysis in the Intelligence Hub. When it's ready, review and confirm it: Radar designs its plan based on it.",
  "El Radar diseña su plan de señales sobre tu análisis de mercado. Genéralo en el Intelligence Hub y confírmalo.": "Radar designs its signal plan based on your market analysis. Generate it in the Intelligence Hub and confirm it.",
  "Confirma tu análisis de mercado": "Confirm your market analysis",
  "Primero, tu análisis de mercado": "First, your market analysis",
  "Revisar y confirmar": "Review and confirm",
  "Ya está todo lleno: solo falta que lo revises y lo confirmes. Es lo que le dice a la plataforma sobre qué mercado investigar.": "Everything is filled in: you just need to review and confirm it. It's what tells the platform which market to research.",
  "Aquí se define en qué países investigar, a qué industrias y cargos apuntar y con qué voz escribir. Sin eso, el research saldría sobre el mercado equivocado.": "This is where you define which countries to research, which industries and titles to target and what voice to write in. Without it, the research would cover the wrong market.",
