  "Todavía no hay un plan de señales": "There's no signal plan yet",
  "El Radar necesita saber qué buscar. A partir del contexto de tu empresa y de lo que dice tu Intelligence Hub, la IA diseña un plan con varios detectores (noticias, vacantes, tecnografía, sondeo de sitios web, financiamiento, cambios de liderazgo, licitaciones, presencia local, visitantes web). Tú lo apruebas y desde ahí corre solo.": "Radar needs to know what to look for. Based on your company context and what your Intelligence Hub says, the AI designs a plan with several detectors (news, job openings, technographics, website probing, funding, leadership changes, tenders, local presence, website visitors). You approve it and from then on it runs on its own.",
