  "Últimos {0} días · intención {1}": "Last {0} days · intent {1}",
  "Agregaste «{0}».{1}": "You added “{0}”.{1}",
  "Más de 70 señales listas que van más allá de Apollo: leemos el sitio y el DNS de cada empresa (Meta Business Manager, WhatsApp sin plataforma o con un bot rígido, tiendas en Mercado Libre y Amazon, pasarelas de pago, email marketing, DMARC…) y buscamos su huella pública en internet. Se agregan con un clic, sin costo extra de IA.": "More than 70 ready-made signals that go beyond Apollo: we read each company's website and DNS (Meta Business Manager, WhatsApp with no platform or with a rigid bot, Mercado Libre and Amazon stores, payment gateways, email marketing, DMARC…) and search for its public online footprint. Add them with one click, no extra AI cost.",
  "{0} señales": "{0} signals",
  "Cargando la biblioteca…": "Loading the library…",
  "Busca por lo que vendes: WhatsApp, Meta Ads, marketplaces, pagos, ciberseguridad…": "Search by what you sell: WhatsApp, Meta Ads, marketplaces, payments, cybersecurity…",
  "Ninguna señal coincide. Prueba otra palabra o agrega un detector propio describiéndolo abajo.": "No signals match. Try another word or add your own detector by describing it below.",
  "Diseña tu plan de señales": "Design your signal plan",
  "La IA lee el contexto de tu empresa (qué vendes, a quién, en qué países) y lo que tu Intelligence Hub dice del mercado, y propone entre 5 y 10 detectores: cada uno una forma distinta de encontrar empresas que te necesitan ahora. Después los ajustas, los activas y corren solos.": "The AI reads your company context (what you sell, to whom, in which countries) and what your Intelligence Hub says about the market, and proposes 5 to 10 detectors: each one a different way to find companies that need you now. Then you adjust them, turn them on, and they run on their own.",
  "Generar plan con IA": "Generate plan with AI",
  "Detiene el monitoreo; los detectores no corren hasta reactivarlo": "Stops monitoring; detectors don't run until you turn it back on",
  "Regenerar plan con IA": "Regenerate plan with AI",
  "Reemplaza los detectores propuestos por la IA y el Hub; los que agregaste tú se conservan.": "Replaces the detectors proposed by the AI and the Hub; the ones you added are kept.",
  "Hipótesis del plan": "Plan hypothesis",
  "Vuelve a leer el Intelligence Hub y ajusta los detectores": "Rereads the Intelligence Hub and adjusts the detectors",
  "Vuelve a diseñar el plan desde cero con la IA": "Redesigns the plan from scratch with AI",
  "Monitoreo:": "Monitoring:",
  "≈ {0} crédito{1} de Apollo por corrida en los {2} detectores de empresa activos.": "≈ {0} Apollo credit{1} per run across the {2} active company detectors.",
  "¿Quieres orientar la búsqueda?": "Want to steer the search?",
  "Ej: Quiero clínicas y consultorios en Monterrey y Guadalajara que atiendan por WhatsApp sin automatización. O: Solo empresas de logística en Perú y Chile.": "E.g., I want clinics and medical offices in Monterrey and Guadalajara that serve customers over WhatsApp without automation. Or: Only logistics companies in Peru and Chile.",
