  "Ej: Restaurantes en Lima con más de 200 reseñas que no tengan página web. O: Empresas que usan Salesforce pero no tienen ningún chat en su sitio. O: Que contrataron un gerente de e-commerce hace menos de dos meses.": "E.g., Restaurants in Lima with more than 200 reviews that don't have a website. Or: Companies that use Salesforce but have no chat on their site. Or: That hired an e-commerce manager less than two months ago.",
  "La IA la traduce a la configuración exacta de esta metodología; después puedes ajustar peso y cadencia.": "The AI translates it into the exact configuration for this methodology; afterwards you can adjust weight and cadence.",
