  "Avisos por WhatsApp": "WhatsApp alerts",
  "Cuando el motor encuentre señales nuevas por encima de tu umbral, te mandamos un WhatsApp con cuántas son y la mejor. Los avisos salen desde el número de Predictable, no desde tu canal de campañas.": "When the engine finds new signals above your threshold, we send you a WhatsApp with how many there are and the best one. Alerts come from Predictable's number, not from your campaign channel.",
