  "js/campaign-flow.js no está cargado. Recarga la página.": "js/campaign-flow.js isn't loaded. Reload the page.",
  "js/campaign-builder.js no está cargado. Recarga la página.": "js/campaign-builder.js isn't loaded. Reload the page.",
  "Avisos en el teléfono": "Phone alerts",
  "Este dispositivo recibe una notificación cada vez que un lead te escribe por WhatsApp, email o LinkedIn, aunque Predictable esté cerrado. Al tocarla se abre la conversación.": "This device gets a notification every time a lead messages you on WhatsApp, email or LinkedIn, even when Predictable is closed. Tap it to open the conversation.",
  "Recibe una notificación cuando un lead te escribe por WhatsApp, email o LinkedIn, aunque Predictable esté cerrado. Se activa por dispositivo: hazlo en cada teléfono o computadora donde quieras recibirlas.": "Get a notification when a lead messages you on WhatsApp, email or LinkedIn, even when Predictable is closed. It's turned on per device: do it on every phone or computer where you want them.",
  "En iPhone, Apple solo permite notificaciones a las apps de la pantalla de inicio (iOS 16.4 o más reciente). Son tres pasos:": "On iPhone, Apple only allows notifications for apps on the home screen (iOS 16.4 or later). It takes three steps:",
  "Las notificaciones de Predictable están bloqueadas en este dispositivo. Para activarlas:": "Predictable notifications are blocked on this device. To turn them on:",
  "Solo avisa de mensajes recibidos, nunca de los que envías tú o tus campañas.": "It only alerts you about messages you receive, never the ones you or your campaigns send.",
