  "El contacto respondió pero no está en ninguna lista. Guárdalo para verlo en Listas, enriquecerlo, enrolarlo en campañas y responderle por cualquier canal.": "The contact replied but isn't in any list. Save it to see it in Lists, enrich it, enroll it in campaigns and reply on any channel.",
