  "Respaldo manual: los pasos de LinkedIn ya suben los leads solos. El CSV trae la URL del perfil y los datos de cada lead enrolado para los campos personalizados de tu cuenta ({{company}}, {{position}}…). El texto del mensaje va en la campaña de LinkedIn: su API no acepta texto por lead.": "Manual backup: LinkedIn steps already upload leads automatically. The CSV includes the profile URL and the data for each enrolled lead for your account's custom fields ({{company}}, {{position}}…). The message text goes in the LinkedIn campaign: its API doesn't accept text per lead.",
