  "Ver fuente": "View source",
  "Escribe un mensaje cuyo gancho es esta señal, con las metodologías de venta, el estilo y la base de conocimiento con que entrenaste la IA. Cae en el cuadro de respuesta para que lo edites; nunca se envía solo.": "Write a message hooked on this signal, using the sales methodologies, style and knowledge base you trained the AI with. It lands in the reply box so you can edit it; it's never sent automatically.",
