  "Escribe tu respuesta para LinkedIn…": "Write your LinkedIn reply…",
  "Ni Dripify ni LinkedIn permiten enviar mensajes por API: copiamos tu respuesta y abrimos el perfil para que la pegues en el chat. Enter copia y abre · Shift+Enter, nueva línea.": "Neither Dripify nor LinkedIn allows sending messages via API: we copy your reply and open the profile so you can paste it into the chat. Enter copies and opens · Shift+Enter for a new line.",
  "Copiar y abrir LinkedIn": "Copy and open LinkedIn",
