  "No tienes créditos suficientes para la cadencia recomendada (6 créditos).": "You don't have enough credits for the recommended cadence (6 credits).",
  "Cada tarjeta es un envío. La espera cuenta desde el paso anterior; \"junto con el anterior\" sale a la misma hora. El \"+\" agrega WhatsApp, email, LinkedIn o una condición con ramas Sí / No que se vuelven a unir al final.": "Each card is a send. The wait counts from the previous step; \"together with the previous one\" goes out at the same time. The \"+\" adds WhatsApp, email, LinkedIn or a condition with Yes / No branches that merge back at the end.",
