  "El texto se extrae en tu navegador y queda abajo para que lo revises.": "The text is extracted in your browser and shown below for you to review.",
  "Ej.: 32 % de respuesta con gerentes de operaciones en fintech": "E.g.: 32% reply rate with operations managers at fintechs",
  "Opcional: por qué funciona o cuándo usarlo": "Optional: why it works or when to use it",
  "Resultado que obtuvo": "Result it got",
  "Cuándo usarlo": "When to use it",
  "Aplicar siempre": "Always apply",
  "La IA lo lee en todos los mensajes. Sin marcar, solo entra cuando es relevante para ese paso y ese lead.": "The AI reads it in every message. Unchecked, it's only used when relevant to that step and that lead.",
  "Agregar a la base": "Add to the base",
  "Usar en los mensajes": "Use in messages",
  "La IA lo usa": "The AI uses it",
  "Pausado: la IA no lo usa": "Paused: the AI doesn't use it",
  "se aplica siempre": "always applied",
  "Ver todo": "View all",
  "Todavía no le enseñaste nada a la IA": "You haven't taught the AI anything yet",
  "Hoy escribe con tu contexto de empresa y las tendencias generales. Empieza por lo que más cambia el resultado: tu metodología y 2 o 3 mensajes que ya te dieron respuestas.": "Right now it writes with your company context and general trends. Start with what changes results the most: your methodology and 2 or 3 messages that already got replies.",
  "Mensajes tuyos que obtuvieron respuesta": "Your messages that got replies",
  "Los detectó el bucle de aprendizaje en tus campañas. Guárdalos como script para que la IA los tome como referencia de forma explícita.": "The learning loop detected them in your campaigns. Save them as scripts so the AI uses them explicitly as a reference.",
  "Obtuvo respuesta en una campaña": "Got a reply in a campaign",
  "Guardar como script": "Save as script",
  "← Campañas": "← Campaigns",
  "Entrenar la IA": "Train the AI",
  "Sube tu metodología de venta, los scripts que ya te funcionaron y tu material. Antes de escribir cada mensaje de campaña, la IA busca aquí lo relevante para ese paso y ese lead y lo sigue por encima de las tendencias genéricas. Cada cambio aplica desde el próximo mensaje.": "Upload your sales methodology, the scripts that already worked for you and your materials. Before writing each campaign message, the AI looks here for what's relevant to that step and that lead, and follows it over generic trends. Every change applies from the next message.",
  "+ Agregar": "+ Add",
  "Cargando tu base de entrenamiento…": "Loading your training base…",
