  "Conecta tu CRM, tus automatizaciones y tu IA a Predictable": "Connect your CRM, your automations and your AI to Predictable",
  "Igual que una app se conecta a HubSpot, tu CRM interno (o Zapier, Make, n8n, o un agente de IA) puede leer y escribir en Predictable: subir leads a tus listas, ponerlos en campañas, y enterarse al instante cuando alguien responde, agenda una reunión o aparece una señal de compra. Tu equipo técnico hace la conexión; tú solo creas la clave y les pasas el mensaje de abajo.": "Just like an app connects to HubSpot, your internal CRM (or Zapier, Make, n8n, or an AI agent) can read and write data in Predictable: add leads to your lists, put them in campaigns, and know instantly when someone replies, books a meeting or a buying signal appears. Your technical team makes the connection; you just create the key and send them the message below.",
  "{0} requests en 24 h": "{0} requests in 24 h",
  "Último uso: {0}": "Last used: {0}",
  "Cómo empezar": "Getting started",
  "Mensaje para tu equipo técnico": "Message for your technical team",
  "Cópialo, completa lo que necesitas y envíalo.": "Copy it, fill in what you need and send it.",
  "Abrir documentación pública": "Open public documentation",
