  "Qué se puede hacer": "What you can do",
  "Tu clave nueva: «{0}»": "Your new key: “{0}”",
  "Cópiala ahora: no la volveremos a mostrar.": "Copy it now: we won't show it again.",
  "Guárdala en un gestor de secretos o pásala por un canal seguro. Quien la tenga puede {0} los datos de tu cuenta.": "Store it in a secrets manager or share it over a secure channel. Anyone who has it can {0} your account's data.",
  "Ya la guardé": "I saved it",
  "Revocar": "Revoke",
  "Clave": "Key",
  "Permiso": "Permission",
  "Creada": "Created",
  "Crear una clave": "Create a key",
  "Una clave identifica a un sistema que se conecta a tu cuenta. Crea una por sistema y dale el menor permiso que necesite.": "A key identifies a system that connects to your account. Create one per system and give it the least permission it needs.",
  "Solo lectura — consulta datos": "Read only — queries data",
  "Lectura y escritura — también crea, actualiza y enrola": "Read and write — also creates, updates and enrolls",
  "Tus claves": "Your keys",
  "Última respuesta {0}": "Last response {0}",
  "Tu endpoint respondió {0} en {1} ms. Funciona.": "Your endpoint responded {0} in {1} ms. It works.",
  "La prueba falló: {0}": "The test failed: {0}",
  "Secreto de firma": "Signing secret",
  "Nuevo secreto": "New secret",
  "Intentos": "Attempts",
  "Registrar un webhook": "Register a webhook",
  "Un webhook es una URL de tu sistema a la que Predictable le avisa cada vez que pasa algo. Tu equipo técnico te da la URL (debe empezar con https://).": "A webhook is a URL in your system that Predictable notifies every time something happens. Your technical team gives you the URL (it must start with https://).",
  "Descripción (opcional)": "Description (optional)",
  "CRM interno — producción": "Internal CRM — production",
  "(incluye los que agreguemos en el futuro)": "(includes any we add in the future)",
  "Tus webhooks": "Your webhooks",
  "Cómo verificar la firma: pestaña Referencia → Webhooks.": "How to verify the signature: Reference tab → Webhooks.",
  "Conecta un agente de IA": "Connect an AI agent",
  "MCP (Model Context Protocol) es el estándar con el que los asistentes de IA usan herramientas externas. Conecta Predictable a Claude, ChatGPT, Cursor o tu propio agente y podrás pedirle cosas como «busca los leads que respondieron esta semana por WhatsApp» o «carga estos 40 contactos y ponlos en la campaña de octubre». Usa las mismas claves y permisos que la API: una clave de solo lectura solo deja consultar.": "MCP (Model Context Protocol) is the standard AI assistants use to work with external tools. Connect Predictable to Claude, ChatGPT, Cursor or your own agent and you can ask it things like “find the leads who replied on WhatsApp this week” or “load these 40 contacts and add them to the October campaign.” It uses the same keys and permissions as the API: a read-only key can only query.",
  "URL del servidor": "Server URL",
  "Herramientas disponibles": "Available tools",
  "Esta es la misma documentación que ve tu equipo técnico en la página pública.": "This is the same documentation your technical team sees on the public page.",
