  "Hola, queremos conectar nuestro CRM con Predictable AI.": "Hi, we want to connect our CRM to Predictable AI.",
  "• La clave de API te la paso por un canal seguro (no por correo).": "• I'll send you the API key through a secure channel (not by email).",
  "Lo que necesitamos: [describe aquí qué quieres sincronizar — p. ej. «subir los leads nuevos del CRM a una lista y marcar en el CRM cuando respondan o agenden reunión»].": "What we need: [describe what you want to sync here — e.g. “add new CRM leads to a list and flag them in the CRM when they reply or book a meeting”].",
  "¿Usas HubSpot, Salesforce, Amplemarket, Google Sheets, Notion o ClickUp? Esos se conectan sin programar en": "Using HubSpot, Salesforce, Amplemarket, Google Sheets, Notion or ClickUp? Those connect without code in",
  ". Esta sección es para el CRM propio de tu empresa o lo que tu equipo técnico construya.": ". This section is for your company's own CRM or whatever your technical team builds.",
  "Tu sistema le habla a Predictable": "Your system talks to Predictable",
  "Crea y actualiza contactos sin duplicar (con el id de tu CRM), búscalos, enriquécelos, enrólalos en campañas y consulta mensajes, señales y reuniones.": "Create and update contacts without duplicates (using your CRM's id), search them, enrich them, enroll them in campaigns, and query messages, signals and meetings.",
  "Predictable le avisa a tu sistema": "Predictable notifies your system",
  "Cada respuesta de un lead, cambio de estado, señal del Radar o reunión analizada llega a tu URL en segundos, firmada para que sepas que es nuestra.": "Every lead reply, status change, Radar signal or analyzed meeting reaches your URL within seconds, signed so you know it's from us.",
  "Tu agente de IA opera Predictable": "Your AI agent runs Predictable",
  "Conecta Claude, ChatGPT, Cursor o tu propio agente y pídele en lenguaje natural «carga estos leads y ponlos en la campaña de octubre».": "Connect Claude, ChatGPT, Cursor or your own agent and ask it in plain language: “load these leads and add them to the October campaign.”",
  "Conectar un agente": "Connect an agent",
  "Crea una clave de API": "Create an API key",
  "Una por sistema (por ejemplo, «CRM interno» y «Zapier»), así puedes revocar una sin cortar las demás.": "One per system (for example, “Internal CRM” and “Zapier”), so you can revoke one without cutting off the others.",
  "Pásale a tu equipo técnico el mensaje de abajo": "Send your technical team the message below",
  "Con la documentación y las URLs. La clave, por un canal seguro.": "With the documentation and URLs. Send the key through a secure channel.",
  "Si tu CRM debe enterarse de lo que pasa aquí, registra un webhook": "If your CRM needs to know what happens here, register a webhook",
  "Opcional. Si no puede recibirlos, puede consultar los eventos cada pocos minutos.": "Optional. If it can't receive them, it can poll for events every few minutes.",
  "Verifica que funciona": "Check that it works",
  "Cuando tu sistema haga su primera llamada, la verás en Registro.": "When your system makes its first call, you'll see it in Log.",
  "Del CRM a Predictable": "From the CRM to Predictable",
