  "Todavía no registraste ningún webhook.": "You haven't registered any webhooks yet.",
  "Aún no hay entregas. Aparecen aquí en cuanto ocurre un evento al que un webhook está suscrito.": "No deliveries yet. They show up here as soon as an event a webhook is subscribed to happens.",
  "Reemplaza <TU_CLAVE> por una clave de la pestaña Claves de API (si acabas de crear una en esta sesión, aparece ya puesta).": "Replace <TU_CLAVE> with a key from the API keys tab (if you just created one in this session, it's already filled in).",
  "Pega esto en tu terminal:": "Paste this in your terminal:",
  "Cursor, Windsurf, VS Code y clientes con archivo de configuración": "Cursor, Windsurf, VS Code and clients with a config file",
  "Agrégalo al archivo de servidores MCP (en Cursor: Settings → MCP → Add new server):": "Add it to the MCP servers file (in Cursor: Settings → MCP → Add new server):",
  "Claude, ChatGPT y clientes que solo aceptan una URL": "Claude, ChatGPT and clients that only accept a URL",
  "En «Conectores» → «Agregar conector personalizado», pega esta URL. La clave queda dentro de la URL: usa una de solo lectura si puedes y revócala si la compartes por error.": "In “Connectors” → “Add custom connector”, paste this URL. The key is inside the URL: use a read-only one if you can, and revoke it if you share it by mistake.",
  "Todavía no hubo ninguna llamada. Cuando tu sistema se conecte, la verás aquí.": "No calls yet. When your system connects, you'll see it here.",
  "Aún no hay eventos.": "No events yet.",
