  "En Predictable, entra a": "In Predictable, go to",
  "Desarrolladores → Claves de API": "Developers → API keys",
  "y crea una clave. Se muestra una sola vez: guárdala en un gestor de secretos, nunca en el código ni en el navegador.": "and create a key. It's shown only once: store it in a secrets manager, never in code or in the browser.",
