  "Guías": "Guides",
  "Documentación": "Documentation",
  "Hola, sí me interesa. ¿Hablamos el jueves?": "Hi, yes, I'm interested. Can we talk Thursday?",
  "Autenticación": "Authentication",
  "Cada request lleva la clave en la cabecera `Authorization: Bearer": "Every request carries the key in the `Authorization: Bearer",
  "` (también se acepta `X-API-Key`). Las claves empiezan con `pai_live_`. **Permisos:** una clave de **solo lectura** puede consultar todo; una de **lectura y escritura** además crea, actualiza, enrola y borra. Usa la de menor permiso que tu integración necesite. Una clave revocada deja de funcionar al instante. La API responde siempre con los datos de la cuenta dueña de la clave: nunca ves ni tocas datos de otra cuenta.": "` header (`X-API-Key` is also accepted). Keys start with `pai_live_`. **Permissions:** a **read-only** key can query everything; a **read and write** key can also create, update, enroll and delete. Use the least permission your integration needs. A revoked key stops working immediately. The API always responds with data from the account that owns the key: you never see or touch another account's data.",
  "Paginación y límites": "Pagination and limits",
  "Las listas devuelven `{ data, has_more, next_cursor }`. Para la página siguiente, repite la llamada con `?cursor=": "Lists return `{ data, has_more, next_cursor }`. For the next page, repeat the call with `?cursor=",
  "`. `limit` va de 1 a 200 (50 por defecto). **Sincronización incremental:** guarda la fecha de tu última sincronización y pide `GET /v1/contacts?updated_after=": "`. `limit` ranges from 1 to 200 (50 by default). **Incremental sync:** store the time of your last sync and request `GET /v1/contacts?updated_after=",
  "`. **Límite de ritmo:** 120 requests por minuto por clave. Las cabeceras `X-RateLimit-Limit` y `X-RateLimit-Remaining` te dicen cuánto te queda; al pasarte recibes `429 rate_limited`: espera unos segundos y reintenta. **Lotes:** hasta 500 contactos por `POST /v1/contacts/bulk` y por enrolamiento; hasta 100 contactos por enriquecimiento.": "`. **Rate limit:** 120 requests per minute per key. The `X-RateLimit-Limit` and `X-RateLimit-Remaining` headers tell you how much you have left; if you go over, you get `429 rate_limited`: wait a few seconds and retry. **Batches:** up to 500 contacts per `POST /v1/contacts/bulk` and per enrollment; up to 100 contacts per enrichment.",
  "Los errores devuelven el código HTTP correspondiente y `{ \"error\": { \"code\", \"message\", \"request_id\" } }`. El `message` está escrito para personas; decide con el `code`.": "Errors return the matching HTTP status code and `{ \"error\": { \"code\", \"message\", \"request_id\" } }`. The `message` is written for people; base your logic on the `code`.",
  "Falta un parámetro o no tiene el formato correcto.": "A parameter is missing or has the wrong format.",
  "La clave falta, no existe o fue revocada.": "The key is missing, doesn't exist or was revoked.",
  "La clave es de solo lectura.": "The key is read-only.",
  "El recurso no existe o no es de tu cuenta.": "The resource doesn't exist or isn't in your account.",
  "La operación choca con el estado actual.": "The operation conflicts with the current state.",
  "Más de 120 requests por minuto.": "More than 120 requests per minute.",
  "Error nuestro: reintenta y, si se repite, escríbenos con el request_id.": "Our error: retry and, if it happens again, contact us with the request_id.",
  "Registra una URL **https** (en Desarrolladores → Webhooks o con `POST /v1/webhooks`) y Predictable le enviará un `POST` con cada evento que elijas. Responde con un código **2xx en menos de 10 segundos**; si no, reintentamos con espera creciente (1 min, 5 min, 30 min, 2 h, 6 h, 12 h, 24 h). Tras 50 fallos seguidos el webhook se desactiva y lo ves en la app. Cada envío lleva las cabeceras `Predictable-Event`, `Predictable-Delivery` (úsala para no procesar dos veces la misma entrega) y `Predictable-Signature: t=": "Register an **https** URL (in Developers → Webhooks or with `POST /v1/webhooks`) and Predictable will send it a `POST` for each event you choose. Respond with a **2xx code within 10 seconds**; otherwise we retry with increasing backoff (1 min, 5 min, 30 min, 2 h, 6 h, 12 h, 24 h). After 50 consecutive failures the webhook is disabled and you'll see it in the app. Each delivery includes the headers `Predictable-Event`, `Predictable-Delivery` (use it to avoid processing the same delivery twice) and `Predictable-Signature: t=",
  "`, donde la firma es `HMAC-SHA256(secreto, \"": "`, where the signature is `HMAC-SHA256(secret, \"",
  ".\")` en hexadecimal. **Verifica siempre la firma** antes de confiar en el contenido.": ".\")` in hex. **Always verify the signature** before trusting the content.",
  "Si tu sistema no puede recibir webhooks, consulta `GET /v1/events?created_after=": "If your system can't receive webhooks, poll `GET /v1/events?created_after=",
  "` cada pocos minutos: es la misma información (se guarda 30 días).": "` every few minutes: it's the same information (kept for 30 days).",
  "Predictable también es un servidor **MCP** (Model Context Protocol): conecta Claude, ChatGPT, Cursor o tu propio agente y podrá consultar y operar tu cuenta con las mismas herramientas y permisos que la API REST (una herramienta por operación: `contacts_list`, `contacts_bulk_upsert`, `campaigns_enroll`, `messages_list`…). Transporte: Streamable HTTP. Autenticación: la misma clave, en `Authorization: Bearer": "Predictable is also an **MCP** (Model Context Protocol) server: connect Claude, ChatGPT, Cursor or your own agent and it can query and operate your account with the same tools and permissions as the REST API (one tool per operation: `contacts_list`, `contacts_bulk_upsert`, `campaigns_enroll`, `messages_list`…). Transport: Streamable HTTP. Authentication: the same key, in `Authorization: Bearer",
  "Solo URL": "URL only",
