  "No pudimos cargar tu entrenamiento": "We couldn't load your training",
  "Reintentar": "Retry",
  "Elige los libros con los que entrenas a tu equipo. El coach los aplica en la reunión y las campañas al escribir cada mensaje. Hasta {0} por destino.": "Choose the books you train your team with. The coach applies them in meetings, and campaigns apply them when writing each message. Up to {0} per destination.",
  "Tu Predictable": "Your Predictable",
  "Entrena la IA con la forma de vender de tu empresa": "Train the AI on how your company sells",
  "Cada empresa vende distinto. Lo que configures aquí lo aplican el Meeting Coach, los mensajes de tus campañas, el diseño de cadencias con IA y el botón «Redactar con IA» de la Bandeja. Nada se inventa: la IA solo usa lo que tú le das y lo que ya está en tu Contexto.": "Every company sells differently. What you set up here is applied by the Meeting Coach, your campaign messages, AI cadence design and the “Write with AI” button in the Inbox. Nothing is made up: the AI only uses what you give it and what's already in your Context.",
  "Ver lo que sabe tu IA": "See what your AI knows",
  "Sin metodologías para el coach, sigue con Neuroventas (la doctrina de siempre). Los principios de cada libro están resumidos con palabras propias: para entrenar con el texto de un libro que tengas, súbelo en la Base de conocimiento.": "With no methodologies selected, the coach sticks with Neuroselling (the usual doctrine). Each book's principles are summarized in our own words: to train with the text of a book you own, upload it to the Knowledge base.",
  "Por defecto": "Default",
  "Arrastra un PDF, .txt o .md, o haz clic para elegirlo": "Drag a PDF, .txt or .md file, or click to choose one",
  "PDF hasta 20 MB (unas 100 páginas). Para un libro largo, sube los capítulos que más usas.": "PDF up to 20 MB (about 100 pages). For a long book, upload the chapters you use most.",
  "Pega tus notas de un libro, tu guion de llamada, tus respuestas a objeciones, tu oferta…": "Paste your notes from a book, your call script, your objection responses, your offer…",
  "Entrenar con este texto": "Train with this text",
  "Llegaste al máximo de {0} documentos: borra uno para agregar otro.": "You've reached the maximum of {0} documents: delete one to add another.",
  "Subir archivo": "Upload file",
  "Pegar texto": "Paste text",
  "Qué es": "What it is",
  "Ej: Playbook comercial 2026": "E.g.: Sales playbook 2026",
  "Entrena a": "Trains",
  "Esto es lo que la IA aprendió. Corrígelo si algo no representa a tu empresa: lo que guardes es lo que usa.": "This is what the AI learned. Correct anything that doesn't represent your company: what you save is what it uses.",
  "Guardar corrección": "Save correction",
  "Borrar documento": "Delete document",
  "Borrar": "Delete",
  "Lo que sabe tu IA": "What your AI knows",
  "El texto exacto que se añade a las instrucciones de cada motor.": "The exact text added to each engine's instructions.",
  "No se pudo cargar la vista previa: {0}": "Couldn't load the preview: {0}",
  "DOCTRINA DEL COACH {0} {1}": "COACH DOCTRINE {0} {1}",
  "Todavía no hay nada entrenado para {0}: se usa el criterio general de Predictable con tu Contexto.": "Nothing trained for {0} yet: Predictable's general criteria are used with your Context.",
  "Entrenado con: {0}": "Trained with: {0}",
  "Máximo {0} metodologías: más marcos a la vez diluyen el consejo.": "Maximum {0} methodologies: more frameworks at once dilute the advice.",
  "Neuroventas": "Neuroselling",
  "Véndele a la mente, no a la gente": "Sell to the mind, not the person",
  "Primero el miedo y la seguridad, luego la emoción, al final los datos. Es la doctrina por defecto del coach.": "Fear and safety first, then emotion, data last. It's the coach's default doctrine.",
  "Descubrimiento en Situación → Problema → Implicación → Necesidad-beneficio.": "Discovery through Situation → Problem → Implication → Need-payoff.",
  "Matthew Dixon y Brent Adamson": "Matthew Dixon and Brent Adamson",
  "Enseñar un insight que reencuadra el problema, adaptarlo a cada perfil y tomar el control.": "Teach an insight that reframes the problem, tailor it to each persona and take control.",
  "Contrato inicial, embudo del dolor y calificar presupuesto y decisión antes de presentar.": "Up-front contract, pain funnel, and qualifying budget and decision before presenting.",
  "Jack Napoli y Dick Dunkel (PTC)": "Jack Napoli and Dick Dunkel (PTC)",
  "Calificación de deals complejos: métricas, quién firma, criterios, proceso, dolor, champion y competencia.": "Qualifying complex deals: metrics, economic buyer, criteria, process, pain, champion and competition.",
  "Vender la brecha entre el estado actual del cliente y el que desea.": "Sell the gap between the customer's current state and the one they want.",
  "Negociación táctica": "Tactical negotiation",
  "Empatía táctica, espejo, etiquetado y preguntas calibradas para negociar y manejar objeciones.": "Tactical empathy, mirroring, labeling and calibrated questions to negotiate and handle objections.",
  "Matthew Dixon y Ted McKenna": "Matthew Dixon and Ted McKenna",
  "Vencer la indecisión: recomendar, limitar opciones y quitar el riesgo de la mesa.": "Overcome indecision: recommend, limit options and take risk off the table.",
  "Aaron Ross y Marylou Tyler": "Aaron Ross and Marylou Tyler",
  "Outbound especializado: mensajes cortos, de persona a persona, y pedir dirección antes que reunión.": "Specialized outbound: short, person-to-person messages, and ask for a referral before asking for a meeting.",
  "Prospección fanática": "Fanatical prospecting",
  "Constancia multicanal y la fórmula de 5 pasos para pedir la reunión.": "Multichannel consistency and the 5-step formula to ask for the meeting.",
  "Influencia": "Influence",
  "Reciprocidad, compromiso, prueba social real, autoridad, simpatía, escasez verdadera y unidad.": "Reciprocity, commitment, real social proof, authority, liking, genuine scarcity and unity.",
  "Preguntar por hechos del pasado, no por opiniones del futuro: los cumplidos no son señales.": "Ask about past facts, not future opinions: compliments aren't signals.",
  "Vender es humano": "To sell is human",
  "Sintonía, claridad y pitches en forma de pregunta; asuntos útiles y específicos.": "Attunement, clarity and pitches framed as questions; useful, specific subject lines.",
  "Libro de ventas": "Sales book",
  "Caso de éxito": "Case study",
