  "Metodologías de venta": "Sales methodologies",
  "Estilo de comunicación": "Communication style",
  "Cómo le habla tu empresa a sus prospectos. Aplica a los mensajes de campaña, a las respuestas de la Bandeja y a las frases que el coach te sugiere decir. El tono base e idioma siguen en tu Contexto.": "How your company talks to prospects. Applies to campaign messages, Inbox replies and the lines the coach suggests you say. Base tone and language stay in your Context.",
  "Coach y reglas del equipo": "Coach and team rules",
  "Lo que ninguna metodología sabe: cómo quieres que te hable el coach y las reglas que tu equipo nunca rompe.": "What no methodology knows: how you want the coach to talk to you and the rules your team never breaks.",
  "Base de conocimiento": "Knowledge base",
  "Sube lo que hace única a tu empresa: libros, tu playbook, casos, precios, competencia o llamadas que salieron bien. La IA lo destila en principios que puedes revisar y corregir.": "Upload what makes your company unique: books, your playbook, case studies, pricing, competition or calls that went well. The AI distills it into principles you can review and correct.",
