  "Cómo suena tu equipo": "How your team sounds",
  "Ej: como un socio que ya resolvió esto en 40 empresas del sector; seguro, cálido y sin exagerar.": "E.g.: like a partner who has already solved this at 40 companies in the industry; confident, warm and never over the top.",
  "Palabras y expresiones que sí usan": "Words and phrases you do use",
  "Ej: \"operación\", \"equipo comercial\", \"sin fricción\", nombre del producto siempre como \"Predictable\".": "E.g.: \"operations\", \"sales team\", \"frictionless\", product name always as \"Predictable\".",
  "Palabras prohibidas": "Banned words",
  "Ej: \"sinergia\", \"disruptivo\", \"solución integral\", \"estimado\", \"espero que estés bien\".": "E.g.: \"synergy\", \"disruptive\", \"end-to-end solution\", \"dear\", \"hope you're doing well\".",
  "Ejemplos reales de tu voz": "Real examples of your voice",
  "Pega 2 o 3 mensajes que tu equipo envió y funcionaron. La IA imita el tono y el ritmo, nunca copia su contenido.": "Paste 2 or 3 messages your team sent that worked. The AI mimics their tone and rhythm, never copies their content.",
  "Personalidad del coach": "Coach personality",
  "Ej: háblame como mi director comercial: exigente, directo, que me corrija si hablo de precio antes de tiempo.": "E.g.: talk to me like my sales director: demanding, direct, and correct me if I bring up price too early.",
  "Siempre": "Always",
  "Ej: proponer una prueba piloto de 30 días; mencionar que implementamos en 2 semanas; cerrar con una fecha concreta.": "E.g.: propose a 30-day pilot; mention we implement in 2 weeks; close with a specific date.",
  "Ej: dar descuentos en la primera reunión; hablar mal de la competencia; prometer integraciones que no existen.": "E.g.: give discounts in the first meeting; badmouth competitors; promise integrations that don't exist.",
  "El archivo de texto es muy grande: pega solo las partes clave.": "The text file is too large: paste only the key parts.",
