  "Agrega a tus SDRs en Miembros. Solo aparecen las personas cuyo perfil dice «{0}».": "Add your SDRs in Members. Only people whose profile says “{0}” appear.",
  "Ir a Miembros": "Go to Members",
  "El ranking se ordena por resultados: reuniones, respuestas o sus tasas. Los envíos se muestran como contexto y no suman puntos. Las tasas se miden sobre las personas a las que se les escribió por primera vez en el período (sus respuestas y reuniones cuentan aunque lleguen después), y con menos de {0} personas no compiten. Las diferencias son contra el mismo tramo de {1}.": "The ranking is sorted by results: meetings, replies or their rates. Sends are shown for context and don't add points. Rates are measured on the people first contacted in the period (their replies and meetings count even if they come later), and people with fewer than {0} don't compete. Changes are compared with the same stretch of {1}.",
