  "No pudimos calcular la rampa: {0}": "We couldn't calculate the ramp: {0}",
  "Semana a semana desde su fecha de inicio, contra la mediana de sus compañeros en esa misma semana de antigüedad. Solo cuentan las semanas que cada compañero ya cumplió, y la mediana necesita al menos {0} compañeros.": "Week by week from their start date, compared with the median of their teammates at the same week of tenure. Only weeks each teammate has already completed count, and the median needs at least {0} teammates.",
