  "Columna IA de la lista": "List AI column",
  "Usa la respuesta de una Columna IA de Listas («¿vende en Mercado Libre?», «¿cuántas sucursales?»). Solo va por Sí si la celda tiene respuesta con evidencia y cumple la regla; «No encontrado» o sin responder va por No. Si la celda sigue en cola, el lead espera a que termine.": "Uses the answer from a Lists AI column (“Do they sell on Mercado Libre?”, “How many branches?”). It only goes down Yes if the cell has an answer with evidence that meets the rule; “Not found” or unanswered goes down No. If the cell is still queued, the lead waits until it finishes.",
