  "Celular, fijo o conmutador según el plan de numeración de cada país (el mismo tipo que guarda el enriquecimiento); «sin WhatsApp» = WhatsApp ya rechazó un envío a ese número (#131026). Por confirmar = el número no lo dice (p. ej. México): se envía igual.": "Mobile, landline or switchboard based on each country's numbering plan (the same type enrichment saves); “not on WhatsApp” = WhatsApp already rejected a send to that number (#131026). Unconfirmed = the number doesn't say (e.g., Mexico): we send anyway.",
  "No se pudo reiniciar el número: {0}": "Couldn't reset the number: {0}",
  ": {0} créditos por email": ": {0} credits per email",
  "{0} por teléfono": "{0} per phone",
  "Si Apollo no lo encuentra, se busca en cascada{0}. Se cobra solo lo que se encuentra{1}, también con tu propio Apollo.": "If Apollo doesn't find it, we run a waterfall search{0}. You're only charged for what's found{1}, even with your own Apollo.",
  "Los emails sin verificar se revisan con {0} y los inválidos se descartan.": "Unverified emails are checked with {0} and invalid ones are discarded.",
  "el teléfono de {0} contacto{1} (y su email si falta)": "the phone for {0} contact{1} (and email if missing)",
  "el email de {0} contacto{1} que ya tiene{2} teléfono": "the email for {0} contact{1} with a phone already{2}",
  "({0} ya tenían los datos o se están buscando y se omiten)": "({0} already had the data or are being searched, so they're skipped)",
  "Se buscará {0} vía Apollo. Costo en Apollo: 8 créditos por teléfono y 2 por email, solo cuando Apollo lo encuentra (con tu propia cuenta de Apollo conectada no gastas créditos de predictable.ai). Corre en segundo plano — puedes seguir usando la app; los resultados aparecen solos en la tabla.": "We'll look up {0} via Apollo. Apollo cost: 8 credits per phone and 2 per email, only when Apollo finds it (with your own Apollo account connected you don't spend predictable.ai credits). It runs in the background — you can keep using the app; results appear in the table on their own.",
  "Buscando en {0} cuentas.": "Searching {0} accounts.",
  "El dominio acepta cualquier dirección: no se puede confirmar el buzón": "The domain accepts any address: the mailbox can't be confirmed",
  "Riesgoso": "Risky",
  "Listo: las campañas vuelven a intentar este WhatsApp.": "Done: campaigns will try this WhatsApp again.",
