  "Guardando parte {0} de {1}…": "Saving part {0} of {1}…",
  "Registro importado: {0} números nuevos.": "Registry imported: {0} new numbers.",
  "Por {0}": "By {0}",
  ", descargado el {0}": ", downloaded on {0}",
  ", vigente hasta el {0}": ", valid until {0}",
  "Archivo {0}": "File {0}",
  "{0} en el registro.": "{0} in the log.",
  "Se cuentan identificadores (emails, teléfonos, dominios y perfiles), no personas: la baja de un lead suprime cada dato suyo.{0}": "We count identifiers (emails, phones, domains and profiles), not people: a lead's opt-out suppresses every piece of their data.{0}",
  "(el registro se actualiza cada {0} días)": "(the registry is updated every {0} days)",
  "Vigente hasta{0}": "Valid until{0}",
  "Hasta {0} números se guarda el archivo completo. Si es más grande, se cruza en tu navegador con los teléfonos de tus contactos y solo se guardan los que coinciden: los contactos que agregues después no quedan cruzados hasta la próxima importación. La importación nueva de un registro reemplaza a la anterior.": "Up to {0} numbers, the whole file is saved. If it's larger, it's matched in your browser against your contacts' phones and only the matches are saved: contacts you add later aren't matched until the next import. A new import of a registry replaces the previous one.",
  "El archivo traía {0} números; {1} coinciden con tus {2} contactos y quedaron en la lista ({3} nuevos).": "The file had {0} numbers; {1} match your {2} contacts and were added to the list ({3} new).",
  ", {0} no válidos": ", {0} invalid",
  "{0} números del archivo: {1} nuevos, {2} renovados{3}.": "{0} numbers in the file: {1} new, {2} renewed{3}.",
  "{0} números de la importación anterior ya no venían y se quitaron (quedan en el registro).": "{0} numbers from the previous import were no longer included and were removed (they stay in the log).",
  "Vencida el {0}": "Expired on {0}",
  "Vigente hasta el {0}": "Valid until {0}",
