  "Dominio": "Domain",
  "El lead pidió no recibir más mensajes": "The lead asked not to receive more messages",
  "Enlace de baja del correo": "Email unsubscribe link",
  "Botón «Darse de baja» de WhatsApp": "WhatsApp “Unsubscribe” button",
