  "Registros oficiales": "Official registries",
  "Agregados por tu equipo": "Added by your team",
  "Tu empresa crea su cuenta de proveedor en repep.profeco.gob.mx, compra las listas de su región y descarga el archivo. PROFECO actualiza las listas cada 15 días.": "Your company creates its provider account at repep.profeco.gob.mx, buys the lists for its region and downloads the file. PROFECO updates the lists every 15 days.",
  "Tu empresa se registra en el portal de trámites de la CRC y consulta sus números (uno a uno, masiva de hasta 10.000 o web service). Sube aquí los números que salieron excluidos. La CRC indica consultar antes de cada contacto.": "Your company registers on the CRC's online services portal and checks its numbers (one by one, in bulk up to 10,000 or via web service). Upload the numbers that came back as excluded here. The CRC says to check before each contact.",
  "Tu empresa consulta con la API de la AAIP (con sus credenciales) o en nollame.aaip.gob.ar. Sube aquí los números inscritos. La AAIP indica consultar al menos cada 30 días.": "Your company checks with the AAIP API (using its own credentials) or at nollame.aaip.gob.ar. Upload the registered numbers here. The AAIP says to check at least every 30 days.",
  "En el Portal del Proveedor del SERNAC tu empresa ve las solicitudes «No Molestar» que la nombran. Sube aquí esos números. Según el SERNAC, la solicitud rige desde que se hace.": "In SERNAC's Portal del Proveedor, your company sees the “No Molestar” requests that name it. Upload those numbers here. According to SERNAC, a request applies from the moment it's made.",
  "Tu empresa se registra en el Procon-SP para acceder a la lista de bloqueo de telemarketing y descarga el archivo. Según el Procon-SP, un número no se llama desde el día 30 de su inscripción.": "Your company registers with Procon-SP to access the telemarketing block list and downloads the file. According to Procon-SP, a number can't be called starting on day 30 after it's registered.",
  "La lista de supresión todavía no está activada en la base de datos (falta aplicar la migración 20261017000004_suppression.sql).": "The suppression list isn't enabled in the database yet (migration 20261017000004_suppression.sql still needs to be applied).",
