  "En la lista hoy": "On the list today",
  "Todavía no hay nadie. Las bajas que pidan tus leads por WhatsApp, email o LinkedIn llegan aquí solas; también puedes agregar contactos o importar un registro oficial.": "No one here yet. Opt-outs your leads request via WhatsApp, email or LinkedIn show up here on their own; you can also add contacts or import an official registry.",
  "quitado de la lista queda": "removed from the list stays",
  "quitados de la lista quedan": "removed from the list stay",
  "Agregar a la lista": "Add to list",
  "Un email, teléfono, dominio (toda la empresa) o perfil de LinkedIn por línea. O sube un CSV: se toma cada celda que lo parezca.": "One email, phone, domain (the whole company) or LinkedIn profile per line. Or upload a CSV: every cell that looks like one is picked up.",
  "Motivo (opcional): cliente actual, pidió no ser contactado por teléfono…": "Reason (optional): current client, asked not to be contacted by phone…",
