  "Sube el archivo que tu empresa descargó o el resultado de su consulta. Predictable no consulta ni descarga los registros por ti: el acceso es de tu empresa.": "Upload the file your company downloaded or the result of its lookup. Predictable doesn't check or download the registries for you: access belongs to your company.",
