  "Cuándo y por qué se suprimió a cada contacto, con la prueba. Nada se borra: lo que se quita queda aquí con su motivo.": "When and why each contact was suppressed, with proof. Nothing is deleted: anything removed stays here with its reason.",
  "Buscar email, teléfono, dominio o perfil": "Search email, phone, domain or profile",
