  "¿Por qué se quita de la lista? (queda en el registro)": "Why remove it from the list? (it stays in the log)",
  "Ver más": "See more",
  "A estos contactos Predictable no les escribe ni les llama. Antes de cada envío, la campaña revisa esta lista: si el lead está suprimido en ese canal, el paso se omite con el motivo y sigue con el siguiente. Cuando un lead pide la baja por cualquier canal, se suprimen todos sus datos en todos los canales.": "Predictable never messages or calls these contacts. Before each send, the campaign checks this list: if the lead is suppressed on that channel, the step is skipped with the reason and the cadence moves on to the next one. When a lead opts out on any channel, all their data is suppressed on every channel.",
