  "Todavía no tienes un sitio conectado.": "You don't have a website connected yet.",
  "Crea tu widget en la pestaña «Sitios», pega el código en tu web y cada formulario o clic de WhatsApp llega aquí con su cronómetro.": "Create your widget in the “Websites” tab, paste the code on your site, and every form submission or WhatsApp click lands here with its timer running.",
  "Crear mi widget": "Create my widget",
  "Últimos {0} días": "Last {0} days",
  "Sin leads inbound en este período. Cuando lleguen verás aquí cuánto tarda cada SDR en hacer el primer contacto.": "No inbound leads in this period. When they arrive, you'll see how long each SDR takes to make first contact.",
  "Contactados en ≤ {0} min": "Contacted in ≤ {0} min",
  "Pendientes": "Pending",
  "El primer contacto es el primer mensaje que sale al lead desde la Bandeja o una campaña (cualquier canal), o «Ya lo contacté». La respuesta automática del sitio no cuenta: es la máquina, no el SDR. El % en ≤ {0} min es sobre todos los leads del período, contactados o no.": "First contact is the first message sent to the lead from the Inbox or a campaign (any channel), or “I already contacted them”. The website's auto-reply doesn't count: that's the machine, not the SDR. The % within ≤ {0} min is based on all leads in the period, contacted or not.",
  "{0} es responsable del tratamiento de los datos personales que nos compartes en este formulario: nombre, email, teléfono o WhatsApp, empresa, cargo y el mensaje que escribas, además de la página desde la que nos escribes.": "{0} is responsible for processing the personal data you share with us in this form: name, email, phone or WhatsApp, company, title and the message you write, plus the page you're writing to us from.",
  "Puedes pedirnos en cualquier momento acceder a tus datos, corregirlos, eliminarlos u oponerte a su uso, o retirar tu consentimiento, escribiendo a {0}. Si nos escribes por WhatsApp, también puedes responder «BAJA» para que no te volvamos a escribir.": "You can ask us at any time to access, correct or delete your data, object to its use, or withdraw your consent by writing to {0}. If you write to us on WhatsApp, you can also reply “STOP” so we don't message you again.",
  "{0} · lista «{1}»": "{0} · “{1}” list",
  "Últimos 30 días: {0} envíos · {1} clics directos a WhatsApp · {2} bloqueados por spam · {3} leads (90 días)": "Last 30 days: {0} submissions · {1} direct clicks to WhatsApp · {2} blocked as spam · {3} leads (90 days)",
  "El widget": "The widget",
  "Campos del formulario": "Form fields",
  "El nombre siempre se pide. Mientras más corto, más leads: email o WhatsApp, empresa y listo.": "Name is always required. The shorter the form, the more leads: email or WhatsApp, company, done.",
  "Privacidad y consentimiento": "Privacy and consent",
  "El aviso sugerido es un punto de partida para Latam; revísalo con tu asesor legal. Cada envío guarda el texto exacto que aceptó el visitante, la hora y la página.": "The suggested notice is a starting point for Latin America; review it with your legal advisor. Each submission stores the exact text the visitor accepted, the time and the page.",
  "Usar el aviso sugerido": "Use the suggested notice",
  "({0} créditos si encuentra el email, con la cuenta de Apollo compartida)": "({0} credits if it finds the email, with the shared Apollo account)",
  "Enriquecer con Apollo al llegar{0}": "Enrich with Apollo on arrival{0}",
  "({0} créditos por lead)": "({0} credits per lead)",
  "Investigar con IA al llegar: verifica el cargo e investiga la empresa{0}": "Research with AI on arrival: verifies the title and researches the company{0}",
  "Al llegar un lead": "When a lead arrives",
  "Los créditos se descuentan de la cuenta de quien recibe el lead. Sin saldo, el lead entra igual, sin enriquecer.": "Credits are charged to the account of whoever receives the lead. With no balance, the lead still comes in, just not enriched.",
  "Tamaños: {0}. Países en inglés, como en tu ICP (Mexico, Colombia, Brazil…).": "Sizes: {0}. Countries in English, as in your ICP (Mexico, Colombia, Brazil…).",
  "Pega el código en tu sitio (antes de </body>). Funciona en WordPress, Wix, Shopify, Webflow o HTML propio.": "Paste the code on your site (before </body>). Works on WordPress, Wix, Shopify, Webflow or custom HTML.",
  "Nuevo sitio": "New website",
  "{0} tu primer contacto.": "{0} your first contact.",
  "Cada lead de tu web, contactado en minutos": "Every lead from your website, contacted in minutes",
  "Un botón de WhatsApp y un formulario corto para tu sitio. Cada lead llega a la lista del SDR que le toca, con su página de origen, sus UTM y el consentimiento registrado, y un cronómetro corre hasta el primer contacto.": "A WhatsApp button and a short form for your website. Each lead lands in the list of the assigned SDR, with its source page, UTMs and recorded consent, and a timer runs until first contact.",
  "{0} tu primer contacto": "{0} your first contact",
  "Acepto que mis datos se usen para contactarme por WhatsApp, teléfono o email sobre mi solicitud, según el aviso de privacidad.": "I agree that my data may be used to contact me by WhatsApp, phone or email about my request, as described in the privacy notice.",
