  "Aviso de privacidad": "Privacy notice",
  "Los usamos solo para responder a tu solicitud y contactarte por WhatsApp, teléfono o email sobre nuestros productos y servicios. No los vendemos ni los compartimos con terceros, salvo con los proveedores que nos ayudan a operar (alojamiento, mensajería y CRM), que los tratan por cuenta nuestra.": "We use it only to respond to your request and contact you by WhatsApp, phone or email about our products and services. We don't sell it or share it with third parties, except with the providers that help us operate (hosting, messaging and CRM), who process it on our behalf.",
  "Tratamos tus datos conforme a la ley de protección de datos de tu país (por ejemplo, la LFPDPPP en México, la Ley 1581 de 2012 en Colombia, la LGPD en Brasil, la Ley 25.326 en Argentina, la Ley 19.628 en Chile y la Ley 29733 en Perú).": "We process your data in accordance with your country's data protection law (for example, the LFPDPPP in Mexico, Law 1581 of 2012 in Colombia, the LGPD in Brazil, Law 25,326 in Argentina, Law 19,628 in Chile and Law 29733 in Peru).",
