  "Sale por el WhatsApp de quien recibe el lead. No cuenta como primer contacto.": "Sent from the WhatsApp of whoever receives the lead. Doesn't count as first contact.",
  "Enrutamiento": "Routing",
  "Para repartir leads, primero arma la nómina de tu equipo en «Equipo». Solo se reparte a personas de esa nómina.": "To route leads, first build your team roster in “Team”. Leads are only routed to people on that roster.",
  "Los leads de este sitio llegan a ti. Repartirlos entre el equipo lo configura un administrador o director.": "Leads from this website come to you. Routing them across the team is set up by an admin or director.",
  "Reparto": "Distribution",
