  "Usa la historia real con esta persona. Nunca se envía solo.": "Uses your real history with this person. It's never sent automatically.",
  "Envíalo desde tu canal o enrólala en una campaña desde Listas.": "Send it from your channel or enroll them in a campaign from Lists.",
  "Cuando alguien que ya te compró o te respondió bien se muda a otra empresa, esa empresa es la reunión más cálida que vas a conseguir. El Radar chequea a tus champions con Apollo (y, si Apollo no los ubica, con una búsqueda web pública) y te avisa con la señal «Tu champion se mudó a…». No se lee LinkedIn por API ni se scrapea.": "When someone who already bought from you or responded well moves to another company, that company is the warmest meeting you'll ever get. Radar checks your champions with Apollo (and, if Apollo can't place them, with a public web search) and alerts you with the signal “Your champion moved to…”. LinkedIn isn't read via API or scraped.",
  "Activar seguimiento": "Turn on tracking",
  "Corre como un detector de personas (10 créditos cada 30 días). Con la cuenta de Apollo de la plataforma, cada persona encontrada cuesta 2 créditos; con tu propio Apollo, lo paga tu cuenta.": "Runs as a people detector (10 credits every 30 days). With the platform's Apollo account, each person found costs 2 credits; with your own Apollo, your account pays.",
  "cada {0} días": "every {0} days",
  "{0} chequeos cada 30 días": "{0} checks every 30 days",
  "Seguimiento encendido": "Tracking on",
