  "Rechequea cada {0} días · tope {1} chequeos cada 30 días{2}": "Rechecks every {0} days · cap of {1} checks every 30 days{2}",
  "{0} champions en seguimiento.": "{0} champions tracked.",
  "Asunto: {0}": "Subject: {0}",
  "Sigue a quienes ya te compraron o te respondieron bien: si se mudan de empresa, la nueva es una señal. Se activa en la pestaña Champions.": "Track people who already bought from you or responded well: if they move companies, the new one is a signal. Turn it on in the Champions tab.",
