  "Listo: el seguimiento corre con el monitoreo del Radar.": "Done: tracking runs with Radar monitoring.",
  "Listo. El seguimiento corre con el monitoreo del Radar: actívalo para que empiece a chequear.": "Done. Tracking runs with Radar monitoring: turn it on so checks can start.",
