  "Redactando…": "Writing…",
  "Redactar otro": "Write another",
  "El seguimiento de champions todavía no está disponible: falta aplicar la migración 20261018170000_champion_watch.sql.": "Champion tracking isn't available yet: the 20261018170000_champion_watch.sql migration hasn't been applied.",
