  "(agrega tus clientes en el Contexto)": "(add your clients in Context)",
  "Todavía no sigues a nadie. Marca a tus champions con la estrella en Listas, acepta los sugeridos o agrega a los contactos de tus clientes actuales.": "You're not tracking anyone yet. Star your champions in Lists, accept the suggestions or add contacts from your current clients.",
