  "lead inbound espera": "inbound lead is waiting for",
  "leads inbound esperan": "inbound leads are waiting for",
  "Reparte créditos a los espacios de tus clientes y ve cuánto gastó cada uno": "Distribute credits to your clients' workspaces and see how much each one spent",
  "No se pudo cargar el consumo: {0}": "Couldn't load usage: {0}",
  "· {0} son del plan y vencen al renovarse": "· {0} are from your plan and expire at renewal",
  "Créditos de tu cuenta (para repartir){0}": "Credits in your account (to distribute){0}",
  "Créditos asignados a {0} espacio{1}": "Credits assigned to {0} workspace{1}",
  "Espacios con saldo bajo": "Workspaces with low balance",
  "Tope de gasto mensual": "Monthly spending cap",
  "Sin tope": "No cap",
  "Avisar con saldo menor o igual a": "Alert when balance is at or below",
  "Sin alerta": "No alert",
  "El tope cuenta el mes calendario: al llegar a él, las acciones que cobran créditos se frenan en ese espacio hasta el mes siguiente. Vacío = sin tope.": "The cap counts the calendar month: once it's reached, actions that charge credits are paused in that workspace until the next month. Empty = no cap.",
  "Nota (opcional)": "Note (optional)",
  "Ej. bolsa de octubre": "E.g., October allotment",
  "{0} vencen con tu plan": "{0} expire with your plan",
  "Asignar": "Assign",
