  "Movimiento": "Transaction",
  "Nota": "Note",
  "Ningún espacio gastó créditos entre el {0} y el {1}.": "No workspace spent credits between {0} and {1}.",
  "Créditos netos: lo gastado menos lo que se devolvió (por ejemplo, un email que Apollo no encontró). Los repartos entre tu cuenta y los espacios no cuentan como consumo. Las fechas van en tu hora local.": "Net credits: what was spent minus what was refunded (for example, an email Apollo didn't find). Transfers between your account and workspaces don't count as usage. Dates are in your local time.",
  "Nota de la revisión:": "Review note:",
  "Nombre de la agencia": "Agency name",
  "Países donde trabajas": "Countries you work in",
  "Verticales (separadas por coma)": "Verticals (comma-separated)",
  "SaaS B2B, logística, salud": "B2B SaaS, logistics, healthcare",
  "Qué hace tu agencia (opcional, se muestra en el directorio)": "What your agency does (optional, shown in the directory)",
  "Mostrar en el directorio público de agencias": "Show in the public agency directory",
  "Ver el directorio": "View the directory",
  "Créditos por espacio": "Credits per workspace",
  "Compras una vez en tu cuenta y repartes a cada cliente. Lo que asignas sale primero de la bolsa de tu plan y vence con ella; las recargas no vencen. Si borras un cliente, su saldo vuelve a tu cuenta.": "You buy once in your account and distribute to each client. What you assign comes first from your plan's allotment and expires with it; top-ups don't expire. If you delete a client, its balance returns to your account.",
  "Créditos que gastó cada espacio por función, para refacturar a tus clientes.": "Credits each workspace spent by feature, so you can bill your clients.",
  "Predictable para agencias": "Predictable for agencies",
  "Si gestionas la prospección de varios clientes, cada uno puede tener su propio Predictable (Contexto, Radar, Listas, Campañas) dentro de tu cuenta: tú compras los créditos y los repartes, y ves cuánto gastó cada cliente para refacturarle. Envía la ficha de tu agencia; la aprobamos a mano.": "If you run prospecting for multiple clients, each one can have its own Predictable (Context, Radar, Lists, Campaigns) inside your account: you buy the credits, distribute them, and see how much each client spent so you can bill them. Submit your agency profile; we approve it manually.",
  "Ficha de tu agencia": "Your agency profile",
  "Es la que aparece en el directorio público de agencias. Solo se publica cuando la aprobamos.": "This is what appears in the public agency directory. It's only published once we approve it.",
  "No se pudo guardar la ficha: {0}": "Couldn't save the profile: {0}",
