  "Mes pasado": "Last month",
  "Para abrir espacios de clientes tu agencia necesita, además de la ficha aprobada, un plan": "To open client workspaces, besides an approved profile your agency needs an active",
  "activo. Puedes enviar la ficha antes.": "plan. You can submit your profile before that.",
  "Tu ficha ya fue revisada. Para cambiar nombre, sitio, países o verticales escríbenos y la revisamos de nuevo. Mostrarla u ocultarla del directorio lo decides tú.": "Your profile has already been reviewed. To change the name, website, countries or verticals, message us and we'll review it again. Showing or hiding it in the directory is up to you.",
  "Guardar ficha": "Save profile",
  "Estás dentro del espacio de un cliente. Los créditos y el consumo de tus clientes se gestionan desde tu cuenta: usa «Volver a mi cuenta».": "You're inside a client's workspace. Your clients' credits and usage are managed from your account: use “Back to my account”.",
