  "Los créditos de este espacio los asigna tu agencia desde su cuenta (Agencia → Créditos por espacio).": "Credits for this workspace are assigned by your agency from its account (Agency → Credits per workspace).",
  "Llamada terminada: {0}.": "Call ended: {0}.",
