  "Calificación": "Qualification",
  "Transcripción": "Transcript",
  "Escuchar grabación": "Listen to recording",
  "El agente devuelve llamadas, confirma o reprograma reuniones y califica a quien ya mostró interés.": "The agent returns calls, confirms or reschedules meetings, and qualifies people who already showed interest.",
  "Nunca llama en frío": "Never cold-calls",
  ", siempre dice que es un asistente con IA y ofrece pasar con una persona.": ", always says it's an AI assistant and offers to transfer to a person.",
  "Activar el agente de voz": "Turn on the voice agent",
  "Nombre del asistente": "Assistant name",
  "Número para pasar con una persona (opcional)": "Number to transfer to a person (optional)",
  "Si lo dejas vacío, cuando el lead pida una persona el agente acuerda que alguien del equipo lo llame.": "If you leave it empty, when the lead asks for a person the agent arranges for someone on the team to call them.",
  "Duración máxima de cada llamada": "Maximum length of each call",
  "Grabar el audio de las llamadas": "Record call audio",
  "Siempre se transcribe y el agente lo avisa al inicio. Si grabas, el agente también avisa que la llamada se graba y, si el lead no acepta, se borra el audio. Sin grabación, el audio se borra del proveedor apenas guardamos la transcripción.": "Calls are always transcribed and the agent says so at the start. If you record, the agent also says the call is being recorded and, if the lead doesn't agree, the audio is deleted. Without recording, the audio is deleted from the provider as soon as we save the transcript.",
  "Lo que exige cada país": "What each country requires",
  "Resumen orientativo, no es asesoría legal: revisa con tu abogado antes de grabar.": "A general summary, not legal advice: check with your lawyer before recording.",
  "Costo: {0} créditos por minuto conectado ({1} a Argentina). Si no contesta, no cuesta.": "Cost: {0} credits per connected minute ({1} to Argentina). If they don't answer, it's free.",
  "¿Para qué es la llamada?": "What's the call for?",
  "El lead me pidió que lo llamáramos (fuera de la Bandeja)": "The lead asked us to call them (outside the Inbox)",
  "Cómo lo pidió: «en el evento X», «por teléfono el lunes»…": "How they asked: “at event X”, “by phone on Monday”…",
  "Elige el evento de tu Google Calendar…": "Choose the event from your Google Calendar…",
  "Al reprogramar, el agente ofrece tus horarios libres reales y mueve el evento al que acuerden.": "When rescheduling, the agent offers your actual free times and moves the event to the one you agree on.",
  "No se puede llamar todavía:": "Can't call yet:",
  "Así empieza la llamada": "This is how the call starts",
  "Horarios que puede ofrecer: {0}": "Times it can offer: {0}",
  "Se reservan {0} créditos ({1} min máx.) y se cobran {2} por minuto conectado. Lo que no se use vuelve a tu saldo.": "{0} credits are reserved ({1} min max.) and {2} are charged per connected minute. Anything unused goes back to your balance.",
  "Llamando a {0}. El resultado aparece en la ficha y en la Bandeja.": "Calling {0}. The result appears on the lead record and in the Inbox.",
