  "El agente de voz todavía no está activado en el servidor (falta aplicar la migración).": "The voice agent isn't enabled on the server yet (the migration hasn't been applied).",
  "En llamada…": "On a call…",
  "Llamando…": "Calling…",
  "Se movió el evento en tu Google Calendar.": "The event was moved in your Google Calendar.",
  "Se anotó la confirmación en tu Google Calendar.": "The confirmation was noted in your Google Calendar.",
  "Sin llamadas todavía. El agente llama solo a quien pidió que lo llamaran, tiene una reunión o ya mostró interés: se presenta como asistente con IA, ofrece pasar con una persona y deja aquí la transcripción, el resumen y el siguiente paso. Se cobra por minuto conectado; si no contesta, no cuesta.": "No calls yet. The agent only calls people who asked to be called, have a meeting or already showed interest: it introduces itself as an AI assistant, offers to transfer to a person, and leaves the transcript, summary and next step here. You're charged per connected minute; if they don't answer, it's free.",
  "El proveedor de voz todavía no está activado en la plataforma: puedes dejar esto listo, pero no se podrá llamar hasta que lo esté.": "The voice provider isn't enabled on the platform yet: you can set this up now, but you won't be able to call until it is.",
  "El número para pasar con una persona debe ir con el prefijo del país (por ejemplo +52…).": "The number to transfer to a person must include the country code (for example +52…).",
  "Ponle un nombre al asistente.": "Give the assistant a name.",
