  "Llamar con el agente de voz": "Call with the voice agent",
  "La reunión": "The meeting",
  "Conecta Google Calendar en Integraciones para elegir el evento, ofrecer horarios libres reales y moverlo solo.": "Connect Google Calendar in Integrations to choose the event, offer real free times and move it automatically.",
