  "Revisado contra tu lista «No contactar» (bajas y registros «No llamar» que cargaste en Campañas → Bajas y exclusiones).": "Checked against your Do-not-contact list (opt-outs and “Do not call” registries you uploaded in Campaigns → Opt-outs and exclusions).",
