  "¿Eliminar la regla «{0}»? Su historial se borra con ella; las tareas y los leads que creó se quedan.": "Delete the rule “{0}”? Its history is deleted with it; the tasks and leads it created stay.",
  "La campaña «{0}» no está activa: actívala en Campañas o elige otra.": "The campaign “{0}” isn't active: activate it in Campaigns or choose another.",
  "«{0}» necesita leads: pon «Buscar decisores» antes.": "“{0}” needs leads: add “Find decision-makers” before it.",
  "puntaje ≥ {0}": "score ≥ {0}",
  "Cuando pase algo, Predictable hace el siguiente paso": "When something happens, Predictable takes the next step",
  "Reglas sin código que encadenan el Radar, tus listas, el enriquecimiento, la investigación con IA y tus campañas. Lo que gasta créditos o envía mensajes espera tu aprobación, con el costo a la vista; cuando confíes en una regla, pásala a automática con un tope diario.": "No-code rules that chain together Radar, your lists, enrichment, AI research and your campaigns. Anything that spends credits or sends messages waits for your approval, with the cost shown upfront; once you trust a rule, switch it to automatic with a daily cap.",
  "+ Nueva regla": "+ New rule",
  "Nada por aprobar": "Nothing to approve",
  "Cuando una regla quiera gastar créditos o enviar mensajes, la ejecución aparece aquí con su costo estimado.{0}": "When a rule wants to spend credits or send messages, the run shows up here with its estimated cost.{0}",
