  "Con aprobación": "With approval",
  "(recomendado): cada ejecución que gasta créditos o envía mensajes espera en «Por aprobar».": "(recommended): every run that spends credits or sends messages waits in “Awaiting approval”.",
  "con tope diario. Lo que pase el tope espera tu aprobación.": "with a daily cap. Anything over the cap waits for your approval.",
  "Créditos por día": "Credits per day",
  "Leads por día": "Leads per day",
  "Cada ejecución puede costar": "Each run can cost",
  "por {0} lead{1}. Con tu propio Apollo conectado, el email y el teléfono los paga tu cuenta y cuesta menos.": "for {0} lead{1}. With your own Apollo connected, email and phone are paid by your account and cost less.",
  "Eliminar regla": "Delete rule",
  "({0} créditos)": "({0} credits)",
  "¿Aprobar {0} ejecuciones? Pueden costar hasta {1} créditos.": "Approve {0} runs? They can cost up to {1} credits.",
  "Cuando el Radar te entrega una señal (el lote diario de «Nuevas»).": "When Radar delivers a signal to you (the daily “New” batch).",
  "Lead nuevo en una lista": "New lead in a list",
  "Cuando entra un lead a una lista (desde Buscar, el Radar, una importación o a mano).": "When a lead is added to a list (from Search, Radar, an import or manually).",
  "Respuesta en la Bandeja": "Reply in the Inbox",
  "Cuando un lead responde. Positiva o negativa se decide por frases claras («me interesa», «agendemos», «no me interesa», «darme de baja»…); una respuesta dudosa no dispara nada.": "When a lead replies. Positive or negative is decided by clear phrases (“I'm interested”, “let's schedule”, “not interested”, “unsubscribe me”…); an ambiguous reply doesn't trigger anything.",
  "Campaña terminada sin respuesta": "Campaign completed with no reply",
  "Cuando un lead recorre toda la cadencia de una campaña y no respondió.": "When a lead goes through a campaign's entire cadence without replying.",
  "Cuando marcas a un lead como «Reunión conseguida» (en Listas o en la Bandeja).": "When you mark a lead as “Meeting booked” (in Lists or the Inbox).",
  "Cuando el lead pasa a «Reunión tomada» (también al cerrar la reunión en el Meeting Coach).": "When the lead moves to “Meeting held” (also when you close the meeting in Meeting Coach).",
  "Buscar decisores de la empresa": "Find the company's decision-makers",
  "Toma los decisores de la señal (o los busca en Apollo) y elige los que coinciden con el cargo y la seniority de tu ICP. Los guarda en una lista y revela su email.": "Takes the decision-makers from the signal (or finds them in Apollo) and picks the ones that match your ICP's title and seniority. Saves them to a list and reveals their email.",
  "Agregar a una lista": "Add to a list",
  "Copia los leads a otra lista (sin duplicar).": "Copies the leads to another list (no duplicates).",
  "Email personal y, si quieres, teléfono. Corre en el servidor como «Enriquecer seleccionados».": "Personal email and, if you want, phone. Runs on the server like “Enrich selected”.",
  "Verifica que sigan en la empresa, investiga la empresa y propone el ángulo. Una investigación de menos de 30 días no se vuelve a pagar.": "Verifies they're still at the company, researches the company and suggests the angle. Research less than 30 days old isn't charged again.",
  "Enrolar en una campaña": "Enroll in a campaign",
  "Los enrola en una campaña activa. La campaña envía los mensajes.": "Enrolls them in an active campaign. The campaign sends the messages.",
  "Crear una tarea": "Create a task",
  "Una tarea por lead en CRM → Tareas. Usa {nombre}, {empresa} y {senal} en el título.": "One task per lead in CRM → Tasks. Use {nombre}, {empresa} and {senal} in the title.",
  "Avisarme": "Notify me",
  "Aviso por push (si activaste las notificaciones) y/o por WhatsApp al número de Radar → Avisos.": "Push notification (if you turned on notifications) and/or WhatsApp to the number in Radar → Alerts.",
  "Señal fuerte → 3 decisores → enriquecer → investigar → campaña": "Strong signal → 3 decision-makers → enrich → research → campaign",
  "El momento de una señal se enfría rápido. Llega primero a los que deciden, con contexto de la empresa, sin escribir a mano. Con aprobación: tú ves el costo antes.": "A signal's moment cools off fast. Reach the decision-makers first, with company context, without writing by hand. With approval: you see the cost first.",
  "Señal del Radar → decisores a una lista + tarea de revisión": "Radar signal → decision-makers to a list + review task",
  "Para revisar cada cuenta antes de escribir: los decisores quedan listos en una lista y te queda la tarea con la señal.": "To review each account before writing: the decision-makers are ready in a list and you get a task with the signal.",
  "Lead nuevo en una lista → investigar con IA": "New lead in a list → research with AI",
  "Cada lead que entra a la lista llega a Campañas con su ángulo y su puesto verificado.": "Every lead added to the list reaches Campaigns with its angle and a verified title.",
  "Respuesta positiva → tarea para hoy + aviso": "Positive reply → task for today + alert",
  "La velocidad de respuesta a un lead interesado pesa más que el texto: te avisa al instante y te deja la tarea.": "How fast you respond to an interested lead matters more than the copy: you're alerted instantly and get a task.",
  "Responder a {nombre} y proponer una reunión": "Reply to {nombre} and propose a meeting",
  "Respuesta negativa → lista de no interesados": "Negative reply → not-interested list",
  "Separa a quien dijo que no, para no volver a escribirle desde otra campaña y revisar el motivo.": "Separates people who said no, so you don't message them again from another campaign and can review the reason.",
  "Campaña sin respuesta → lista de reciclaje + tarea de llamada": "Campaign with no reply → recycle list + call task",
  "Quien no respondió por escrito puede responder a una llamada o a otra campaña más adelante.": "People who didn't reply in writing may answer a call or another campaign later on.",
  "Reunión agendada → investigar + aviso": "Meeting booked → research + alert",
  "Llega a la reunión con la empresa investigada y el ángulo listo para el Meeting Coach.": "Show up to the meeting with the company researched and the angle ready for Meeting Coach.",
  "Reunión tomada → tarea de seguimiento": "Meeting held → follow-up task",
  "Que el siguiente paso acordado no se pierda.": "So the agreed next step doesn't get lost.",
  "Enviar el siguiente paso a {nombre} ({empresa})": "Send the next step to {nombre} ({empresa})",
