  "Por llamar": "To call",
  "No tienes llamadas pendientes": "You have no pending calls",
  "Cuando una campaña llega a un paso de llamada, la tarea aparece aquí con su guion. También puedes llamar a cualquier lead desde Listas o la Bandeja.": "When a campaign reaches a call step, the task shows up here with its script. You can also call any lead from Lists or the Inbox.",
