  "Transcribiendo…": "Transcribing…",
  "Todavía no hay llamadas": "No calls yet",
  "Las llamadas del dialer y de tu proveedor aparecen aquí con su resultado, grabación y transcripción.": "Calls from the dialer and your provider show up here with their outcome, recording and transcript.",
  "Dialer de Predictable": "Predictable dialer",
  "Llama desde el navegador con tu micrófono, con grabación, transcripción y el Meeting Coach en vivo. Cada minuto se paga en créditos según el país.": "Call from your browser with your microphone, with recording, transcription and live Meeting Coach. Each minute is paid in credits based on the country.",
  "Todavía no está activo en esta cuenta de Predictable. Mientras tanto puedes conectar tu proveedor abajo.": "It isn't active on this Predictable account yet. In the meantime, you can connect your provider below.",
  "Te ven con el número": "They see you as",
  "Contesta y teclea este código:": "Answer and enter this code:",
  "Ya lo tecleé": "I entered it",
  "Número verificado: ya puedes llamar.": "Number verified: you can call now.",
  "Todavía no se confirma. Si colgaste antes de teclear el código, pide otra llamada.": "Not confirmed yet. If you hung up before entering the code, request another call.",
  "Tu número con prefijo del país": "Your number with country code",
  "Cambiar número": "Change number",
  "Verificar mi número": "Verify my number",
  "¿Prefieres un número local de tu país? Pídelo a soporte: lo asignamos a tu cuenta.": "Prefer a local number in your country? Ask support and we'll assign one to your account.",
  "Llamar con el dialer de Predictable": "Call with the Predictable dialer",
