  "Usar para llamar": "Use for calling",
  "Volver a conectar": "Reconnect",
  "Conectar paso a paso": "Connect step by step",
  "¿Todavía no tienes cuenta?": "Don't have an account yet?",
  "¿Ya usas un proveedor de llamadas?": "Already use a calling provider?",
  "Conéctalo y llama con un clic desde Predictable: tus minutos los sigue cobrando tu proveedor, y cada llamada queda registrada aquí con su grabación.": "Connect it and call in one click from Predictable: your provider still bills your minutes, and every call is logged here with its recording.",
  "Número sin lead": "Number with no lead",
  "Esta llamada no tiene grabación.": "This call has no recording.",
  "{0} sin teléfono (se omite {1})": "{0} without a phone (skips {1})",
  "Guion IA": "AI script",
  "Recomendado: un guion distinto por lead": "Recommended: a different script for each lead",
  "Mi guion": "My script",
  "Días que la cadencia espera la llamada": "Days the cadence waits for the call",
  "Este paso crea una tarea en Campañas → Llamadas con el guion. Cuando marcas el resultado, la cadencia sigue: «Reunión agendada» y «No interesado» la detienen; «Contestó» y «Buzón» se pueden usar en una condición. Si nadie llama en ese plazo, el paso se omite. Sin teléfono, se omite.": "This step creates a task in Campaigns → Calls with the script. When you mark the outcome, the cadence continues: “Meeting booked” and “Not interested” stop it; “Answered” and “Voicemail” can be used in a condition. If no one calls within that window, the step is skipped. With no phone, it's skipped.",
  "La IA escribe el guion de cada lead 24 h antes (apertura, preguntas, objeciones, cierre y mensaje de buzón) con el ángulo de ESTE paso y lo que ya se le envió. Cuesta 2 créditos por guion.": "The AI writes each lead's script 24 h in advance (opening, questions, objections, close and voicemail message) using THIS step's angle and what's already been sent. Costs 2 credits per script.",
  "Hola {{nombre}}, te llamo de… ¿tienes 30 segundos?": "Hi {{nombre}}, I'm calling from… do you have 30 seconds?",
  "El mismo guion para todos los leads; las variables se reemplazan con los datos de cada uno en la tarea de llamar.": "The same script for every lead; variables are replaced with each lead's data in the call task.",
  "el WhatsApp y la llamada": "WhatsApp and the call",
  "la llamada": "the call",
  "el WhatsApp": "WhatsApp",
  "Los WhatsApp salen del número conectado; los emails, de la cuenta elegida. LinkedIn no lleva tope: el ritmo lo decide tu cuenta de LinkedIn. La ventana horaria y los días se aplican en la zona horaria indicada. A los leads de Colombia, además, solo se les envía de lunes a viernes de 7:00 a 19:00 y sábados de 8:00 a 15:00 (hora de Colombia), nunca domingos ni festivos, y un envío por día (Ley 2300).": "WhatsApp messages go out from the connected number; emails, from the chosen account. LinkedIn has no cap: your LinkedIn account sets the pace. The time window and days apply in the selected time zone. Leads in Colombia are also only messaged Monday to Friday from 7:00 to 19:00 and Saturdays from 8:00 to 15:00 (Colombia time), never on Sundays or holidays, and once per day (Ley 2300).",
  "{0}: una llamada no puede salir \"junto con el anterior\": la hace una persona.": "{0}: a call can't go out \"together with the previous one\": a person makes it.",
  "· Guion IA: {0}": "· AI script: {0}",
  "Contestó la llamada": "Answered the call",
  "El SDR marcó «Contestó» en la llamada de esta cadencia. «Reunión agendada» y «No interesado» detienen la campaña solos.": "The SDR marked “Answered” on this cadence's call. “Meeting booked” and “Not interested” stop the campaign on their own.",
  "La llamada cayó en buzón": "The call went to voicemail",
  "La llamada de esta cadencia terminó en buzón de voz (lo marca el SDR o el proveedor).": "This cadence's call ended in voicemail (marked by the SDR or the provider).",
