  "Estas cifras no aparecen en tu Contexto ni en tus documentos: {0}. ¿Son reales y quieres aprobar igual?": "These figures don't appear in your Context or your documents: {0}. Are they real, and do you want to approve anyway?",
  "Publicación manual": "Manual publishing",
  "La publicación automática en LinkedIn todavía no está habilitada en Predictable. Prepara, aprueba y programa tus posts aquí y publícalos con «Copiar y abrir LinkedIn».": "Automatic publishing to LinkedIn isn't enabled in Predictable yet. Prepare, approve and schedule your posts here, and publish them with “Copy and open LinkedIn”.",
  "Conecta tu LinkedIn": "Connect your LinkedIn",
  "Para que Predictable publique en tu perfil a la hora que elijas. Usa el permiso oficial de LinkedIn para publicar; no lee tu perfil ni tus mensajes. Sin conectar, igual puedes copiar y publicar a mano.": "So Predictable can publish to your profile at the time you choose. It uses LinkedIn's official publishing permission; it doesn't read your profile or messages. Without connecting, you can still copy and publish manually.",
  "Conectado como {0}": "Connected as {0}",
  "El permiso vence el {0} (LinkedIn lo da por 60 días).": "The permission expires on {0} (LinkedIn grants it for 60 days).",
