  "Tu contenido en LinkedIn": "Your LinkedIn content",
  "Ideas y posts escritos con tu Contexto, tu análisis de mercado, lo que ve el Radar, lo que te funciona y tu voz entrenada. Nada sale sin tu aprobación, y la IA no inventa casos, clientes ni cifras: si no tienes prueba social cargada, el post no la menciona.": "Ideas and posts written with your Context, your market analysis, what Radar sees, what works for you and your trained voice. Nothing goes out without your approval, and the AI doesn't invent cases, clients or figures: if you haven't added social proof, the post doesn't mention it.",
  "Foco opcional: un tema, un segmento, una objeción, un evento…": "Optional focus: a topic, a segment, an objection, an event…",
