  "La función de contenido todavía no está desplegada en el servidor: puedes preparar y aprobar posts, pero no generarlos con IA ni publicarlos por API.": "The content function isn't deployed on the server yet: you can prepare and approve posts, but not generate them with AI or publish them via API.",
  "Falta aplicar la migración 20261018180010_linkedin_content.sql.": "The 20261018180010_linkedin_content.sql migration hasn't been applied yet.",
  "1 idea nueva en tu tablero.": "1 new idea on your board.",
  "Cambiaste el texto de un post aprobado: vuelve a borrador y tendrás que aprobarlo de nuevo. ¿Guardar?": "You changed the text of an approved post: it goes back to draft and you'll need to approve it again. Save?",
