  "Programado: te avisaremos aquí cuando toque publicarlo.": "Scheduled: we'll remind you here when it's time to publish it.",
  "Copiamos el texto. Si LinkedIn no lo muestra, pégalo. Luego márcalo como publicado.": "We copied the text. If LinkedIn doesn't show it, paste it. Then mark it as published.",
  "Abrimos LinkedIn. Copia el texto desde aquí si no aparece.": "We opened LinkedIn. Copy the text from here if it doesn't appear.",
  "¿Desconectar LinkedIn? Los posts programados para publicarse solos vuelven a «Aprobado».": "Disconnect LinkedIn? Posts scheduled to publish automatically go back to “Approved”.",
