  "Falta el permiso para leer deals, dueños y empresas en HubSpot. Reconecta (o agrega esos alcances a tu app privada).": "Missing permission to read deals, owners, and companies in HubSpot. Reconnect (or add those scopes to your private app).",
  "Elige una lista (el envío automático es por lista).": "Choose a list (automatic sending is per list).",
  "Envío automático apagado para esta lista.": "Automatic sending turned off for this list.",
  "Tu conexión no tiene permiso para leer deals, dueños y empresas. Reconecta HubSpot (o, con una app privada, agrega crm.objects.deals.read, crm.objects.companies.read y crm.objects.owners.read y pega el token de nuevo).": "Your connection doesn't have permission to read deals, owners, and companies. Reconnect HubSpot (or, with a private app, add crm.objects.deals.read, crm.objects.companies.read, and crm.objects.owners.read and paste the token again).",
