  "Tu agenda está pausada": "Your scheduling page is paused",
  "Todavía no activas tu agenda": "You haven't activated your scheduling page yet",
  "Comparte un enlace para que tus leads elijan un horario libre de tu calendario (Google Calendar u Outlook). Úsalo en tus campañas con {{link_agenda}} o desde la Bandeja con «Enviar mi agenda»: al agendar, la cadencia se detiene y el lead pasa a «reunión agendada». Recordatorios por WhatsApp y email contra el no-show.": "Share a link so your leads can pick an open time on your calendar (Google Calendar or Outlook). Use it in your campaigns with {{link_agenda}} or from the Inbox with “Send my scheduling link”: when they book, the cadence stops and the lead moves to “meeting booked.” WhatsApp and email reminders help prevent no-shows.",
  "Revisar y activar": "Review and activate",
