  "Cortas (hasta 5). Las respuestas entran a la nota BANT del traspaso al AE: pregunta lo que de verdad te dice si hay presupuesto, quién decide, qué necesita y para cuándo.": "Short (up to 5). The answers go into the BANT note for the AE handoff: ask what really tells you whether there's budget, who decides, what they need, and by when.",
  "¿Cuántos vendedores tiene tu equipo?": "How many salespeople are on your team?",
  "Obligatoria": "Required",
  "Quitar la pregunta": "Remove question",
  "+ Pregunta": "+ Question",
  "Recordatorios contra el no-show": "No-show reminders",
  "Confirmación al agendar, 24 h antes y 1 h antes, con un enlace para confirmar o reprogramar. Por WhatsApp sale la plantilla aprobada que elijas (si el invitado responde «Confirmo» o «Reprogramar», la reunión se actualiza sola); por email, desde tu cuenta de Apollo.": "Confirmation on booking, 24 h before, and 1 h before, with a link to confirm or reschedule. On WhatsApp, the approved template you choose is sent (if the invitee replies “Confirmo” or “Reprogramar,” the meeting updates automatically); by email, from your Apollo account.",
