  "Cuentas (empresas), pipeline de oportunidades y tareas. Listo para sincronizar con tu CRM por external_id.": "Accounts (companies), opportunity pipeline, and tasks. Ready to sync with your CRM by external_id.",
  "Ver el pipeline": "View the pipeline",
  "Las etapas de tus oportunidades, en orden. Si todavía no tienes pipeline, se crea el de por defecto (Reunión agendada → Reunión tomada → Propuesta → Negociación → Ganada / Perdida).": "Your opportunity stages, in order. If you don't have a pipeline yet, the default one is created (Meeting booked → Meeting held → Proposal → Negotiation → Won / Lost).",
  "Empresas del CRM. Una cuenta por dominio: cada contacto nuevo con dominio crea o reutiliza la suya.": "CRM companies. One account per domain: each new contact with a domain creates or reuses its own.",
  "Texto en el nombre o el dominio.": "Text in the name or domain.",
  "Dominio exacto (se normaliza).": "Exact domain (normalized).",
  "Solo las creadas después de esta fecha (ISO 8601).": "Only those created after this date (ISO 8601).",
  "Busca por": "Looks up by",
  ") y si no por dominio: si existe la actualiza (": ") and otherwise by domain: if it exists, updates it (",
  "), si no la crea y enlaza los contactos y señales del Radar con ese dominio.": "); otherwise creates it and links the contacts and Radar signals with that domain.",
  "Id en tu CRM: actualiza sin duplicar.": "Id in your CRM: updates without duplicating.",
  "La cuenta con sus contactos, oportunidades, tareas abiertas y señales del Radar.": "The account with its contacts, opportunities, open tasks, and Radar signals.",
  "Id de la cuenta.": "Account id.",
  "Actualizar cuenta": "Update account",
  "Cambia firmografía, responsable, notas o el id externo.": "Changes firmographics, owner, notes, or the external id.",
  "Oportunidades con su etapa, monto y moneda local.": "Opportunities with their stage, amount, and local currency.",
  "open = en curso; won = ganadas; lost = perdidas.": "open = in progress; won = won; lost = lost.",
  "Solo las modificadas después de esta fecha (sincronización incremental).": "Only those modified after this date (incremental sync).",
  "Crea una oportunidad (fuente": "Creates an opportunity (source",
  "). Con": "). With",
  "es idempotente: si ya existe, la actualiza (": "it's idempotent: if it already exists, it updates it (",
  "). Una etapa perdida exige": "). A lost stage requires",
  "con «otro»): el motivo alimenta el aprendizaje de la plataforma.": "with “other”): the reason feeds the platform's learning.",
  "Etapa (GET /v1/pipeline). Por defecto, la primera abierta.": "Stage (GET /v1/pipeline). Defaults to the first open one.",
  "Alternativa a company_id; crea la cuenta si no existe.": "Alternative to company_id; creates the account if it doesn't exist.",
  "ISO 4217. Sin conversión de moneda.": "ISO 4217. No currency conversion.",
  "Obligatorio en una etapa perdida.": "Required for a lost stage.",
  "Obligatorio con lost_reason «otro».": "Required when lost_reason is “other”.",
  "Ver oportunidad": "View opportunity",
  "La oportunidad con su historial de etapas (quién la movió: user, coach o api) y sus tareas.": "The opportunity with its stage history (who moved it: user, coach, or api) and its tasks.",
  "Id de la oportunidad.": "Opportunity id.",
  "Actualizar oportunidad": "Update opportunity",
  "Mueve de etapa o cambia monto, moneda, fecha de cierre o responsable. Pasar a una etapa perdida exige": "Moves the stage or changes the amount, currency, close date, or owner. Moving to a lost stage requires",
  "Tareas por lead, cuenta u oportunidad.": "Tasks by lead, account, or opportunity.",
  "open = pendientes; done = hechas.": "open = pending; done = completed.",
  "Solo las que vencen antes de esta fecha.": "Only those due before this date.",
  "Si indicas la oportunidad o el contacto, la cuenta se completa sola.": "If you specify the opportunity or the contact, the account is filled in automatically.",
