  "Invita por correo a una empresa que ya tiene su propia cuenta de Predictable (o va a crearla) para verla y operarla desde la tuya. Ella conserva su cuenta y sus créditos, y puede quitarte el acceso cuando quiera.": "Invite a company by email that already has its own Predictable account (or is about to create one) to view and operate it from yours. It keeps its account and credits, and can remove your access at any time.",
  "Correo de la empresa": "Company email",
