  "Invitar": "Invite",
  "Le enviamos un correo. La empresa tiene que entrar a Predictable con ese mismo correo y aceptar; hasta entonces no tienes acceso a nada de su cuenta.": "We email them. The company must sign in to Predictable with that same email and accept; until then you have no access to anything in their account.",
