  "Acceso a tu cuenta": "Access to your account",
  "Estas agencias quieren gestionar tu cuenta. Si aceptas, podrán entrar a tu cuenta y ver y operar todos tus datos (Contexto, Radar, Listas, Campañas, créditos). Puedes quitarles el acceso cuando quieras.": "These agencies want to manage your account. If you accept, they will be able to enter your account and view and operate all your data (Context, Radar, Lists, Campaigns, credits). You can remove their access at any time.",
  "Aceptar": "Accept",
  "Rechazar": "Decline",
