  // Entrenamiento IA sin metodologías (2026-10-19)
  "Lo que solo sabe tu empresa: playbook, precios, casos, estilo y reglas para el Meeting Coach y tus campañas": "What only your company knows: playbook, pricing, case studies, style and rules for the Meeting Coach and your campaigns",
  "Playbook o guion de ventas": "Sales playbook or script",
  "Tu proceso, cómo calificas, las preguntas que haces y cómo respondes a las objeciones de siempre.": "Your process, how you qualify, the questions you ask and how you answer the usual objections.",
  "Planes, qué incluye cada uno, condiciones y cómo presentas el precio.": "Plans, what each one includes, terms and how you present the price.",
  "Clientes reales: qué problema tenían, qué hicieron contigo y qué resultado lograron.": "Real customers: what problem they had, what they did with you and what result they got.",
  "Contra quién compites, en qué ganas, en qué ganan ellos y qué dices cuando el lead los menciona.": "Who you compete against, where you win, where they win and what you say when the lead mentions them.",
  "Transcripciones de llamadas o mensajes de tu equipo que salieron bien.": "Transcripts of calls or messages from your team that went well.",
  "Producto u otro material": "Product or other material",
  "Fichas del producto, presentación comercial, preguntas frecuentes o cualquier material interno.": "Product sheets, sales deck, FAQs or any internal material.",
  "Material de ventas": "Sales material",
  "1 documento de tu empresa": "1 document from your company",
  "{0} documentos de tu empresa": "{0} documents from your company",
  "Sabe:": "Knows:",
  "Entrenado con:": "Trained with:",
  "Todavía solo sabe lo de tu Contexto global": "For now it only knows what's in your Global context",
  "Enséñale a la IA cómo vende tu empresa": "Teach the AI how your company sells",
  "Qué vendes, a quién y contra quién ya está en tu": "What you sell, to whom and against whom is already in your",
  "Contexto global": "Global context",
  ". Aquí suma lo que solo sabe tu equipo: tu playbook, tus precios, tus casos y cómo hablan. Lo usan el Meeting Coach, los mensajes de tus campañas, el diseño de cadencias y «Redactar con IA» de la Bandeja. Nada se inventa: la IA solo usa lo que tú le das.": ". Here, add what only your team knows: your playbook, your pricing, your case studies and how you talk. The Meeting Coach, your campaign messages, cadence design and the Inbox's «Write with AI» use it. Nothing is made up: the AI only uses what you give it.",
  "Conocimiento de tu empresa": "Your company's knowledge",
  "Sube lo que tu equipo sabe y no está escrito en ningún otro lado: tu forma de vender, tus precios, tus casos y tu competencia. La IA lo resume en principios que puedes revisar y corregir.": "Upload what your team knows and isn't written anywhere else: how you sell, your pricing, your case studies and your competitors. The AI summarizes it into principles you can review and correct.",
  "Cómo habla tu equipo": "How your team talks",
  "Cómo le escribe tu empresa a sus prospectos. Aplica a los mensajes de campaña, a las respuestas de la Bandeja y a las frases que el coach te sugiere decir.": "How your company writes to its prospects. It applies to campaign messages, Inbox replies and the lines the coach suggests you say.",
  "Reglas del equipo": "Team rules",
  "Lo que tu equipo siempre hace, lo que nunca hace y cómo quieres que te hable el coach.": "What your team always does, what it never does and how you want the coach to talk to you.",
  "Lo que más mejora a tu IA": "What improves your AI the most",
  "{0} de {1}": "{0} of {1}",
  "PDF hasta 20 MB (unas 100 páginas). Si es largo, sube solo las partes que tu equipo usa.": "PDF up to 20 MB (about 100 pages). If it's long, upload only the parts your team uses.",
  "Pega tu guion de llamada, tus respuestas a objeciones, tu oferta, un caso de éxito…": "Paste your call script, your objection responses, your offer, a case study…",
  "Todavía no subiste documentos. Empieza por lo que más usa tu equipo: tu playbook o guion de ventas.": "You haven't uploaded any documents yet. Start with what your team uses most: your sales playbook or script.",
  "Tienes cambios sin guardar en el estilo o las reglas.": "You have unsaved changes to the style or rules.",
  "Guardar cambios": "Save changes",
  "Guardado. El coach y las campañas lo usan desde el próximo mensaje.": "Saved. The coach and campaigns use it from the next message.",
  "Escribe un mensaje cuyo gancho es esta señal, con el estilo, las reglas y el conocimiento de tu empresa con que entrenaste la IA. Cae en el cuadro de respuesta para que lo edites; nunca se envía solo.": "Write a message hooked on this signal, using the style, rules and company knowledge you trained the AI with. It lands in the reply box so you can edit it; it's never sent automatically.",
  "Conecta y configura los canales por los que salen tus campañas y llegan las respuestas a la Bandeja. Email, WhatsApp y LinkedIn son los pasos de tus cadencias; Llamadas define con qué llamas desde Listas, la Bandeja y la cola «Por llamar».": "Connect and configure the channels your campaigns send through and your Inbox replies arrive from. Email, WhatsApp and LinkedIn are the steps of your cadences; Calls sets how you call from Lists, the Inbox and the “To call” queue.",
  "Conecta un canal para ver aquí su configuración.": "Connect a channel to see its settings here.",
  "Ver la cola de llamadas": "See the call queue",
  "Ver la cola": "See the queue",
  "Sin conectar. El asistente te guía paso a paso, también si todavía no tienes cuenta.": "Not connected. The wizard guides you step by step, even if you don't have an account yet.",
  "Revisar en Canales": "Review in Channels",
  "Falta el webhook de respuestas": "Replies webhook missing",
  "Una campaña combina Email, WhatsApp, LinkedIn y llamadas en una sola cadencia y se detiene sola cuando el lead responde por cualquier canal. Conecta al menos un canal en «Canales» para empezar.": "A campaign combines Email, WhatsApp, LinkedIn and calls in a single cadence and stops on its own when the lead replies on any channel. Connect at least one channel in “Channels” to get started.",
  "Conectar canales": "Connect channels",
  "Conecta al menos un canal en «Canales»": "Connect at least one channel in “Channels”",
  "Llama con un clic desde Listas, la Bandeja y la cola «Por llamar» de tus campañas: con el dialer de Predictable (grabación, transcripción y Meeting Coach en vivo) o con tu proveedor (CloudTalk, Aircall o Ringover).": "Call with one click from Lists, the Inbox and your campaigns' “To call” queue: with the Predictable dialer (recording, transcription and live Meeting Coach) or with your provider (CloudTalk, Aircall or Ringover).",
