  "Este enlace solo trae el id de una búsqueda guardada en Apollo, y Apollo no permite leerla por API. Ábrela en Apollo, espera a que carguen los filtros (o cambia uno y vuelve a dejarlo) y copia la dirección completa de la barra del navegador.": "This link only carries the id of a search saved in Apollo, and Apollo doesn't let us read it through its API. Open it in Apollo, wait for the filters to load (or change one and set it back) and copy the full address from the browser bar.",
