  "una sola plataforma": "one platform",
  "De la señal de compra al deal cerrado, sin cambiar de herramienta. Cada paso alimenta al siguiente y cada respuesta enseña a la IA qué funciona.": "From buying signal to closed deal, without switching tools. Every step feeds the next, and every reply teaches the AI what works.",
