  "Funciones de Contactar": "Contact features",
  "Diseña la cadencia en una línea de tiempo visual con condiciones («¿leyó el WhatsApp?», «¿aceptó en LinkedIn?»). La IA te recomienda la cadencia según tu mercado.": "Design the cadence on a visual timeline with conditions (“did they read the WhatsApp?”, “did they accept on LinkedIn?”). The AI recommends a cadence for your market.",
