  "Cada mensaje combina mercado, industria, empresa, rol y persona, con tu tono y tus casos reales. Nunca inventa clientes ni cifras. Tú apruebas antes de enviar.": "Each message combines market, industry, company, role and person, in your tone and with your real case studies. It never makes up clients or numbers. You approve before it's sent.",
