  "Lo que nos preguntan antes de empezar.": "What people ask us before they start.",
  "¿Qué incluye la prueba gratis?": "What's included in the free trial?",
  "300 créditos por 30 días si te registras con el email de tu empresa, o 100 sin vencimiento con un email personal. No pedimos tarjeta. Con eso configuras tu contexto, recibes tu análisis de mercado, activas tu primer detector del Radar y lanzas tu primera campaña.": "300 credits for 30 days if you sign up with your work email, or 100 that never expire with a personal email. No card required. That's enough to set up your context, get your market analysis, turn on your first Radar detector and launch your first campaign.",
  "¿Necesito una cuenta de Apollo?": "Do I need an Apollo account?",
  "Sí. Para buscar contactos conectas tu propia cuenta de Apollo (tiene un plan gratuito). Así los datos que revelas son tuyos y no gastan créditos de Predictable.": "Yes. To search contacts you connect your own Apollo account (it has a free plan). That way the data you reveal is yours and doesn't use Predictable credits.",
  "¿Reemplaza a mi CRM?": "Does it replace my CRM?",
  "Puede hacerlo: incluye oportunidades, cuentas y tareas. Si ya usas HubSpot, Pipedrive, Salesforce, Zoho, Kommo, Bitrix24 o RD Station, Predictable AI se conecta y sincroniza en lugar de duplicar.": "It can: it includes opportunities, accounts and tasks. If you already use HubSpot, Pipedrive, Salesforce, Zoho, Kommo, Bitrix24 or RD Station, Predictable AI connects and syncs instead of duplicating.",
  "¿Es seguro enviar por WhatsApp y LinkedIn?": "Is it safe to send on WhatsApp and LinkedIn?",
  "WhatsApp sale por tu número oficial con plantillas aprobadas por Meta, y vigilamos la calidad del número para frenar antes de un bloqueo. En LinkedIn respetamos topes diarios y semanales por cuenta. Toda baja se respeta en todos los canales.": "WhatsApp goes out from your official number with Meta-approved templates, and we watch the number's quality to slow down before a block. On LinkedIn we respect daily and weekly caps per account. Every opt-out is honored on every channel.",
  "¿La IA inventa datos o casos de éxito?": "Does the AI make up data or case studies?",
  "No. Los mensajes solo citan los clientes y resultados que tú cargas. Si una respuesta no tiene evidencia, la marcamos como «No encontrado» en vez de adivinar.": "No. Messages only cite the clients and results you upload. If an answer has no evidence, we mark it “Not found” instead of guessing.",
  "¿Cuál es la diferencia entre Starter y Growth?": "What's the difference between Starter and Growth?",
  "Con Starter tu equipo usa la plataforma. Con Growth nuestro equipo la opera contigo: estrategia, listas, cadencias y mensajes, con revisiones de resultados.": "With Starter, your team uses the platform. With Growth, our team runs it with you: strategy, lists, cadences and messaging, with results reviews.",
  "¿En qué países funciona?": "Which countries does it work in?",
  "En toda Latam y también fuera de ella. Los registros públicos cubren Brasil, México y Colombia, y la plataforma está en español, inglés y portugués.": "All of LATAM and beyond. Public registries cover Brazil, Mexico and Colombia, and the platform is available in Spanish, English and Portuguese.",
  "Deja de": "Stop",
