  "Datos de varias fuentes": "Multi-source data",
  "Columnas IA": "AI columns",
  "Una biblioteca de más de 100 detectores vigila contrataciones, rondas de inversión, cambios de liderazgo, licitaciones, noticias y la huella digital de cada empresa, y te dice quién es el decisor. Cada día recibes las 25 señales con más puntaje.": "A library of 100+ detectors watches hiring, funding rounds, leadership changes, tenders, news and each company's digital footprint, and tells you who the decision maker is. Every day you get the 25 highest-scoring signals.",
  "Datos de contacto de varias fuentes": "Contact data from multiple sources",
  "Buscas personas y empresas por industria, tamaño, país y cargo, y para cada decisor consultamos varias bases de datos en cascada hasta encontrar su email y su móvil. Adaptadas a Latam: teléfonos en el formato de cada país, móvil o fijo, y si tiene WhatsApp. Verificamos cada email y solo pagas por dato encontrado.": "Search people and companies by industry, size, country and title, and for each decision maker we query several databases in a waterfall until we find their email and mobile. Built for LATAM: phone numbers in each country's format, mobile or landline, and whether they're on WhatsApp. We verify every email and you only pay for data found.",
  "Empresas recién constituidas, que crecieron o que cambiaron de actividad en todos los países de Latam, directo de los registros oficiales.": "Newly incorporated companies, companies that grew or changed their line of business, in every LATAM country, straight from the official registries.",
