  "Arma la cadencia como un árbol de decisiones: arrastra email, WhatsApp, LinkedIn o una llamada, y abre ramas según lo que hizo cada lead («¿aceptó en LinkedIn?», «¿leyó el WhatsApp?»). La IA te propone el árbol según tu mercado.": "Build the cadence as a decision tree: drag in email, WhatsApp, LinkedIn or a call, and branch on what each lead did (“accepted on LinkedIn?”, “read the WhatsApp?”). The AI proposes the tree for your market.",
