  "Sofía, vi que FinPago cerró su Serie B y está contratando vendedores en Colombia. Cuando un equipo crece así de rápido, lo primero que se rompe es el seguimiento de los leads. ¿Te muestro cómo lo resolvió otra fintech en 15 minutos?": "Sofía, I saw FinPago closed its Series B and is hiring salespeople in Colombia. When a team grows that fast, the first thing that breaks is lead follow-up. Can I show you how another fintech solved it in 15 minutes?",
