  "Una baja vale en todos los canales": "One opt-out applies to every channel",
  "Si el lead pide no ser contactado, no le vuelve a escribir nadie.": "If the lead asks not to be contacted, nobody writes to them again.",
  "SUNAT (RUC)": "SUNAT (RUC)",
  "Empresas recién inscritas y su actividad.": "Newly registered companies and their activity.",
  "Una herramienta por cada tarea distinta, y ninguna habla con las demás.": "One tool per job, and none of them talk to each other.",
  "Datos y secuencias de email": "Data and email sequences",
  "Grabación y coaching": "Recording and coaching",
