  "Incluye las secuencias de email": "Includes email sequences",
  "Total": "Total",
  "Una plataforma en vez de cuatro, y los datos fluyen de un paso al siguiente.": "One platform instead of four, and data flows from one step to the next.",
  "Una herramienta por categoría: Apollo ya trae secuencias de email, así que no sumamos Instantly ni Lemlist aparte. Precios de lista mensuales publicados por cada proveedor o reportados por terceros en octubre de 2026, plan de entrada, sin impuestos. Gong no publica precios: usamos una estimación de terceros. Las funciones y precios de cada proveedor pueden cambiar. Los canales (tu Apollo, tu WhatsApp Business y tu LinkedIn) se conectan con tus propias cuentas.": "One tool per category: Apollo already includes email sequences, so we don't add Instantly or Lemlist on top. Monthly list prices published by each vendor or reported by third parties in October 2026, entry plan, before taxes. Gong doesn't publish prices: we use a third-party estimate. Each vendor's features and prices may change. Channels (your Apollo, your WhatsApp Business and your LinkedIn) connect with your own accounts.",
  "Nace Eleva": "Eleva is born",
  "Agencia de generación de leads B2B: outbound hecho a mano para empresas de Latam.": "B2B lead generation agency: hand-run outbound for LATAM companies.",
  "reuniones calificadas para más de 50 clientes, con 10x+ de retorno medido en sus cuentas.": "qualified meetings for 50+ clients, with a measured 10x+ return on their accounts.",
  "Úsala tú, o deja que la operemos por ti.": "Run it yourself, or let us run it for you.",
  "Empieza gratis con tu propia empresa. Si prefieres no hacer nada, con Growth nos comprometemos por contrato a entregarte reuniones calificadas.": "Start free with your own company. If you'd rather do nothing, with Growth we commit by contract to delivering qualified meetings.",
  "Tu equipo opera": "Your team runs it",
  "Para que tu equipo genere reuniones desde hoy.": "So your team books meetings starting today.",
  "924 USD al año. Para que tu equipo genere reuniones desde hoy.": "924 USD per year. So your team books meetings starting today.",
  "Growth · Servicio asistido": "Growth · Managed service",
  "Nuestro equipo hace todo el trabajo. Tu equipo solo llega a las reuniones.": "Our team does all the work. Your team just shows up to the meetings.",
  "Reuniones calificadas comprometidas por contrato, cada mes.": "Qualified meetings committed by contract, every month.",
  "Acordamos contigo un número de reuniones al mes según tu mercado y queda en el contrato.": "We agree on a number of meetings per month based on your market, and it goes in the contract.",
  "Sin armar listas": "No list building",
  "Sin escribir mensajes": "No message writing",
  "Sin configurar canales": "No channel setup",
  "Estrategia, listas, mensajes, cadencias y seguimiento a cargo de nuestro equipo": "Strategy, lists, messages, cadences and follow-up handled by our team",
  "Cada reunión llega con el brief del lead y por qué ahora": "Every meeting comes with the lead brief and why now",
  "Toda la plataforma incluida: ves cada envío y cada respuesta": "The full platform included: you see every send and every reply",
  "Revisión mensual de resultados con tu equipo": "Monthly results review with your team",
  "Con Starter tu equipo usa la plataforma. Con Growth nos comprometemos por contrato a un número de reuniones calificadas al mes y nuestro equipo hace todo el trabajo: estrategia, listas, mensajes, cadencias y seguimiento. Tu equipo solo llega a la reunión.": "With Starter, your team uses the platform. With Growth, we commit by contract to a number of qualified meetings per month and our team does all the work: strategy, lists, messages, cadences and follow-up. Your team just shows up to the meeting.",
  "¿De dónde salen los datos de contacto?": "Where does the contact data come from?",
  "De varias bases de datos consultadas en cascada: si una no encuentra el email o el móvil, seguimos con la siguiente. Verificamos cada email, normalizamos cada teléfono al formato de su país y solo cobramos por dato encontrado.": "From several databases queried in a waterfall: if one doesn't find the email or mobile, we move on to the next. We verify every email, normalize every phone number to its country's format and only charge for data found.",
  "En toda Latam y también fuera de ella. Los registros públicos cubren los países de Latam, y la plataforma está en español, inglés y portugués.": "Across LATAM and beyond. Public registries cover the LATAM countries, and the platform is available in Spanish, English and Portuguese.",
